import { GoogleGenAI, Type } from "@google/genai";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, mimeType: string = 'image/jpeg', retryCount = 0): Promise<any> => {
  // 遵循規範：每次調用時才建立實例
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `你是一個專業的名片 OCR 解析器。請精準提取這張名片上的資訊。

            【基本規則】：
            1. 姓名、公司、職稱必須依照原文提取。
            2. 如果原文是英文，請在 translations 中提供對應的繁體中文名稱（若為專有名詞則維持原文）。
            3. 判斷分類：'academic' (學術單位/教授), 'staff' (學校行政人員), 'employer' (企業/業界人員)。

            【回傳格式】：僅回傳 JSON。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "為什麼這樣分類？" },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 無法解析此影像");
    return JSON.parse(text.trim());

  } catch (error: any) {
    if ((error?.message?.includes("503") || error?.status === 503) && retryCount < 2) {
      await sleep(2000);
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB ---
const DB_NAME = 'QSHub_Pro_V1';
const STORE_NAME = 'scans';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore(STORE_NAME, { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCard = async (card: BusinessCardData) => {
  const db = await getDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  tx.objectStore(STORE_NAME).put(card);
};

const loadCards = async (): Promise<BusinessCardData[]> => {
  const db = await getDB();
  return new Promise((resolve) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const request = tx.objectStore(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result || []);
  });
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [viewMode, setViewMode] = useState<'home' | 'camera' | 'tasks' | 'detail' | 'history'>('home');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const filesMap = useRef<Map<string, File | Blob>>(new Map());

  useEffect(() => {
    loadCards().then(data => setCards(data.sort((a,b) => b.scannedAt - a.scannedAt)));
  }, []);

  const handleCapture = async (base64: string) => {
    const taskId = crypto.randomUUID();
    const res = await fetch(`data:image/jpeg;base64,${base64}`);
    filesMap.current.set(taskId, await res.blob());
    setTasks(prev => [{ id: taskId, fileName: 'Camera_Scan.jpg', status: 'pending', progress: 0, batchIndex: 0 }, ...prev]);
    setViewMode('tasks');
  };

  const processQueue = async () => {
    if (isProcessing) return;
    const task = tasks.find(t => t.status === 'pending');
    if (!task) return;

    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const file = filesMap.current.get(task.id);
      if (!file) throw new Error("檔案丟失");

      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
      });

      const data = await extractCardInfo(base64, file.type);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...data,
        scannedAt: Date.now(),
        imageUrl: `data:${file.type};base64,${base64}`
      };

      await saveCard(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
    } catch (e: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: e.message } : t));
    } finally {
      setIsProcessing(false);
    }
  };

  useEffect(() => { processQueue(); }, [tasks, isProcessing]);

  const exportData = () => {
    const sheetData = cards.map(c => ({
      '姓名': `${c.firstName} ${c.lastName}`,
      '單位': c.company,
      '職稱': c.title,
      '分類': c.category,
      'Email': c.email || '',
      '電話': c.phone || '',
      '手機': c.mobile || '',
      '翻譯單位': c.translations?.company || '',
      '時間': new Date(c.scannedAt).toLocaleString()
    }));
    const ws = XLSX.utils.json_to_sheet(sheetData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Cards");
    XLSX.writeFile(wb, `QS_Scan_Export.xlsx`);
  };

  const activeCard = useMemo(() => cards.find(c => c.id === selectedId), [cards, selectedId]);

  return (
    <div className="flex flex-col h-full bg-[#f8fafc]">
      {/* Header */}
      <header className="bg-white border-b px-6 h-16 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
            <i className="fa-solid fa-bolt text-sm"></i>
          </div>
          <span className="font-black tracking-tight text-slate-800">SCANNER PRO</span>
        </div>
        <div className="flex gap-2">
          {cards.length > 0 && (
            <button onClick={exportData} className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600">
              <i className="fa-solid fa-file-export"></i>
            </button>
          )}
          <button onClick={() => setViewMode('history')} className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600 relative">
            <i className="fa-solid fa-clock-rotate-left"></i>
            {cards.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-indigo-600 text-white text-[9px] rounded-full flex items-center justify-center font-bold">{cards.length}</span>}
          </button>
        </div>
      </header>

      {/* Main Area */}
      <main className="flex-1 overflow-hidden relative">
        {viewMode === 'home' && (
          <div className="h-full flex flex-col items-center justify-center p-8 text-center">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center mb-6 text-indigo-500">
              <i className="fa-solid fa-address-card text-4xl"></i>
            </div>
            <h1 className="text-2xl font-black text-slate-800 mb-2">快速名片辨識</h1>
            <p className="text-slate-400 text-sm mb-12 max-w-[240px]">使用 AI 技術自動提取名片資訊並整理為 QS HUB 格式</p>

            <div className="w-full max-w-sm space-y-4">
              <button 
                onClick={() => setViewMode('camera')}
                className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                <i className="fa-solid fa-camera text-xl"></i> 立即掃描
              </button>

              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full bg-white text-slate-700 py-5 rounded-2xl font-bold border-2 border-slate-100 active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                <i className="fa-solid fa-images text-xl text-slate-400"></i> 從相簿選擇
              </button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                const files = e.target.files; if (!files) return;
                const newTasks = Array.from(files).map(f => {
                  const id = crypto.randomUUID();
                  filesMap.current.set(id, f);
                  return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 0 };
                });
                setTasks(prev => [...newTasks, ...prev]);
                setViewMode('tasks');
              }} />
            </div>
          </div>
        )}

        {viewMode === 'camera' && (
          <div className="h-full bg-black">
            <CameraScanner onCapture={handleCapture} onClose={() => setViewMode('home')} />
          </div>
        )}

        {viewMode === 'tasks' && (
          <div className="h-full flex flex-col p-6 bg-white overflow-y-auto custom-scrollbar">
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-black text-xl">處理進度</h2>
              <button onClick={() => setViewMode('home')} className="text-indigo-600 font-bold text-sm">返回首頁</button>
            </div>
            <div className="space-y-4">
              {tasks.length === 0 ? (
                <div className="py-20 text-center text-slate-300 font-bold">目前沒有任務</div>
              ) : (
                tasks.map(t => (
                  <div key={t.id} className="p-4 rounded-2xl border flex items-center gap-4 bg-slate-50">
                    <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center shrink-0 shadow-sm">
                      {t.status === 'completed' ? <i className="fa-solid fa-check text-emerald-500"></i> :
                       t.status === 'processing' ? <i className="fa-solid fa-circle-notch fa-spin text-indigo-500"></i> :
                       t.status === 'error' ? <i className="fa-solid fa-triangle-exclamation text-red-500"></i> :
                       <i className="fa-solid fa-hourglass-start text-slate-300"></i>}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="text-sm font-bold truncate">{t.fileName}</div>
                      <div className="text-[10px] text-slate-400 uppercase tracking-wider">{t.status}</div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {viewMode === 'history' && (
          <div className="h-full flex flex-col bg-slate-50">
            <header className="p-6 bg-white border-b flex items-center justify-between shrink-0">
              <h2 className="font-black text-xl">掃描紀錄</h2>
              <button onClick={() => setViewMode('home')} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center"><i className="fa-solid fa-xmark"></i></button>
