      {viewMode !== 'camera' && (
        <nav className="h-20 bg-white border-t flex items-center justify-around px-4 pb-safe shrink-0">
          <TabIcon icon="fa-house" active={viewMode === 'home'} onClick={() => setViewMode('home')} label="首頁" />
