import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // 核心修復：當 video 標籤準備好且 stream 也有了，再進行連接
  useEffect(() => {
    if (isReady && stream && videoRef.current) {
      const video = videoRef.current;
      video.srcObject = stream;

      // 顯式調用 play 並捕捉可能的錯誤
      const playPromise = video.play();
      if (playPromise !== undefined) {
        playPromise.catch(err => {
          console.error("Video auto-play failed:", err);
          setError("影像播放失敗，請嘗試手動點擊螢幕或重新整理。");
        });
      }
    }
  }, [isReady, stream]);

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          // 簡化約束以提高相容性
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      // 先讓狀態變為 ready，觸發 video 標籤渲染
      setIsReady(true);
    } catch (err: any) {
      console.error("Camera Error:", err);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("請允許相機存取權限。若在 LINE 中，請使用右上角選單並選擇「在瀏覽器開啟」。");
      } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
        setError("找不到相機設備。");
      } else {
        setError(`無法取得相機：${err.message || '未知錯誤'}`);
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // 使用影像實際寬高
      const width = video.videoWidth;
      const height = video.videoHeight;

      if (width === 0 || height === 0) return;

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, width, height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2rem] overflow-hidden relative shadow-2xl">
      {!isReady ? (
        <div className="p-8 text-center animate-in fade-in zoom-in duration-300">
          <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6 text-indigo-400">
             <i className={`fa-solid ${isLoading ? 'fa-circle-notch fa-spin' : 'fa-camera'} text-3xl`}></i>
          </div>

          {error ? (
            <div className="max-w-xs">
              <h3 className="text-white font-bold mb-2 text-lg">哎呀！遇到問題</h3>
              <p className="text-slate-400 text-sm mb-6 leading-relaxed">{error}</p>
              <button 
                onClick={startCamera} 
                className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black shadow-lg shadow-indigo-500/30"
              >
                再次嘗試開啟
              </button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-xl mb-3">準備掃描名片</h3>
              <p className="text-slate-400 text-sm mb-8 leading-relaxed">我們將使用相機來即時擷取名片資訊，請確保環境光線充足。</p>
              <button 
                onClick={startCamera}
                disabled={isLoading}
                className="w-full bg-white text-slate-900 py-4 rounded-2xl font-black shadow-xl active:scale-95 transition-all"
              >
                {isLoading ? '相機啟動中...' : '立即開啟相機'}
              </button>
            </div>
          )}
        </div>
      ) : (
        <>
          {/* 行動裝置必備：muted, playsInline, autoPlay */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="h-full w-full object-cover"
          />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/30 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(0,0,0,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-400 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-400 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-400 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-400 translate-x-1 translate-y-1 rounded-br-lg"></div>

                {/* 掃描線動畫 */}
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent opacity-70 animate-[scan_3s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex flex-col items-center gap-4">
            <p className="text-white/60 text-[10px] font-bold uppercase tracking-widest">對準名片後按下快門</p>
            <button 
              onClick={capture}
              className="w-20 h-20 rounded-full bg-white border-8 border-white/20 flex items-center justify-center shadow-2xl active:scale-90 transition-transform"
            >
              <div className="w-12 h-12 rounded-full bg-indigo-600"></div>
            </button>
          </div>

          <button 
            onClick={() => {
              if (stream) stream.getTracks().forEach(t => t.stop());
              setIsReady(false);
              onClose();
            }}
            className="absolute top-6 right-6 w-10 h-10 bg-black/40 backdrop-blur-md text-white rounded-full flex items-center justify-center border border-white/10"
          >
            <i className="fa-solid fa-xmark"></i>
          </button>
        </>
      )}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default CameraScanner;

