import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHub_Pro_V1';
const STORE_NAME = 'scans';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore(STORE_NAME, { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCard = async (card: BusinessCardData) => {
  const db = await getDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  tx.objectStore(STORE_NAME).put(card);
};

const loadCards = async (): Promise<BusinessCardData[]> => {
  const db = await getDB();
  return new Promise((resolve) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const request = tx.objectStore(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result || []);
  });
};

const App: React.FC = () => {
  const [isLine, setIsLine] = useState(false);
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const filesMap = useRef<Map<string, File | Blob>>(new Map());

  useEffect(() => {
    const ua = navigator.userAgent.toLowerCase();
    setIsLine(ua.indexOf('line') > -1);
    loadCards().then(data => setCards(data.sort((a,b) => b.scannedAt - a.scannedAt)));
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const newTasks = Array.from(files).map((f: any) => {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 0 };
    });
    setTasks(prev => [...newTasks, ...prev]);
    e.target.value = '';
  };

  const processQueue = async () => {
    if (isProcessing) return;
    const task = tasks.find(t => t.status === 'pending');
    if (!task) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const file = filesMap.current.get(task.id);
      if (!file) throw new Error("檔案丟失");
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
      });
      const data = await extractCardInfo(base64, file.type);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...data,
        scannedAt: Date.now(),
        imageUrl: `data:${file.type};base64,${base64}`
      };
      await saveCard(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.filter(t => t.id !== task.id));
    } catch (e: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: e.message } : t));
    } finally {
      setIsProcessing(false);
    }
  };

  useEffect(() => { processQueue(); }, [tasks, isProcessing]);

  return isLine ? (
    <ClassicLayout 
      cards={cards} 
      tasks={tasks} 
      onFileUpload={handleFileUpload} 
    />
  ) : (
    <ModernLayout 
      cards={cards} 
      tasks={tasks} 
      onFileUpload={handleFileUpload}
      filesMap={filesMap}
      setTasks={setTasks}
    />
  );
};

