import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (isReady && stream && videoRef.current) {
      const video = videoRef.current;
      video.srcObject = stream;
      const playPromise = video.play();
      if (playPromise !== undefined) {
        playPromise.catch(err => {
          console.error("Video auto-play failed:", err);
          setError("影像播放失敗，請點擊螢幕重試。");
        });
      }
    }
  }, [isReady, stream]);

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      setIsReady(true);
    } catch (err: any) {
      if (err.name === 'NotAllowedError') {
        setError("請允許相機權限。或在 LINE 點擊右上角「在瀏覽器開啟」。");
      } else {
        setError(`相機啟動失敗：${err.message}`);
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    return () => {
      if (stream) stream.getTracks().forEach(track => track.stop());
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const width = video.videoWidth;
      const height = video.videoHeight;
      if (width === 0) return;
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, width, height);
        const base64 = canvas.toDataURL('image/jpeg', 0.85).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-[#1a0000] rounded-[2.5rem] overflow-hidden relative shadow-2xl">
      {!isReady ? (
        <div className="p-10 text-center">
          <div className="w-24 h-24 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-8 text-[#D4AF37] relative">
             <div className="absolute inset-0 border-2 border-[#D4AF37]/20 rounded-full animate-pulse"></div>
             <i className={`fa-solid ${isLoading ? 'fa-circle-notch fa-spin' : 'fa-camera-retro'} text-4xl`}></i>
          </div>

          {error ? (
            <div className="max-w-xs animate-in slide-in-from-top">
              <h3 className="text-white font-black mb-3 text-xl">稍候重試</h3>
              <p className="text-slate-400 text-xs mb-8 leading-loose tracking-widest">{error}</p>
              <button onClick={startCamera} className="w-full bg-[#800000] text-[#FFD700] py-4 rounded-2xl font-black shadow-xl">重新啟動</button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-black text-2xl mb-4 tracking-tighter">開啟智慧之眼</h3>
              <p className="text-slate-400 text-xs mb-10 leading-loose tracking-widest">對準名片，AI 將為您即時轉譯精準資訊</p>
              <button 
                onClick={startCamera}
                disabled={isLoading}
                className="w-full bg-white text-[#800000] py-5 rounded-2xl font-black shadow-2xl active:scale-95 transition-all"
              >
                {isLoading ? '啟動中...' : '開 啟 鏡 頭'}
              </button>
            </div>
          )}
        </div>
      ) : (
        <>
          <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-cover opacity-80" />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[88%] max-w-sm aspect-[1.6/1] border-2 border-white/20 rounded-3xl relative shadow-[0_0_0_100vmax_rgba(26,0,0,0.7)]">
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-[#D4AF37] -translate-x-1 -translate-y-1 rounded-tl-xl"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-[#D4AF37] translate-x-1 -translate-y-1 rounded-tr-xl"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-[#D4AF37] -translate-x-1 translate-y-1 rounded-bl-xl"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-[#D4AF37] translate-x-1 translate-y-1 rounded-br-xl"></div>

                {/* 佛光掃描線：金黃色 */}
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#FFD700] to-transparent opacity-60 animate-[scan_3.5s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-12 left-0 right-0 flex flex-col items-center gap-6">
            <p className="text-[#FFD700]/50 text-[9px] font-black uppercase tracking-[0.4em]">攝 入 光 明 圓 滿</p>
            <button 
              onClick={capture}
              className="w-22 h-22 rounded-full bg-white border-[10px] border-white/10 flex items-center justify-center shadow-2xl active:scale-90 transition-transform"
            >
              <div className="w-14 h-14 rounded-full bg-[#800000] flex items-center justify-center text-[#FFD700]">
                 <i className="fa-solid fa-bolt-lightning text-xl"></i>
              </div>
            </button>
          </div>

          <button 
            onClick={() => {
              if (stream) stream.getTracks().forEach(t => t.stop());
              setIsReady(false);
              onClose();
            }}
            className="absolute top-8 right-8 w-12 h-12 bg-[#800000]/80 backdrop-blur-md text-[#FFD700] rounded-full flex items-center justify-center border border-white/10 active:scale-90 transition-transform"
          >
            <i className="fa-solid fa-xmark text-xl"></i>
          </button>
        </>
      )}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

