              const res = await fetch(`data:image/jpeg;base64,${b64}`);
              filesMap.current.set(taskId, await res.blob());
              setTasks(prev => [...prev, { id: taskId, fileName: `掃描影像_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-sm p-12 border-2 border-dashed border-slate-200 rounded-[3rem] bg-white shadow-sm hover:border-indigo-300 transition-colors cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl text-indigo-500"></i>
