type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 2);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isExporting, setIsExporting] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };

    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const downloadFile = (blob: Blob, fileName: string) => {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  /**
   * 嚴格執行 QS HUB 格式
   * 根據圖片提供的欄位順序進行映射
   */
  const handleExportAndShare = (filterCategory?: string) => {
    const targetCards = filterCategory 
      ? cards.filter(c => c.category === filterCategory) 
      : cards;

    if (targetCards.length === 0) {
      alert("目前沒有資料可供匯出");
      return;
    }

    setIsExporting(true);

    try {
      // 依照 QS 提供的圖片格式精準映射
      const exportData = targetCards.map(c => {
        const baseData: any = {
          'Source': 'Business Card',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
        };

        if (c.category === 'employer') {
          // Employer 格式: Position, Industry, Company Name...
          return {
            ...baseData,
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Phone (Optional)': c.mobile || c.phone || '',
          };
        } else {
          // Academic/Staff 格式: Job Title, Department, Institution...
          return {
            ...baseData,
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Subject': c.subject || '',
            'Phone (Optional)': c.mobile || c.phone || '',
          };
        }
      });

      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "QS_Hub_Data");

      const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
      const mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      const blob = new Blob([excelBuffer], { type: mimeType });
      const fileName = `QS_Hub_${filterCategory || 'Export'}_${new Date().toISOString().split('T')[0]}.xlsx`;
      const file = new File([blob], fileName, { type: mimeType });

      // 為了解決 Permission Denied， navigator.share 必須在同步程式碼區塊內被「觸發」
      // 如果環境支援分享，立即調用
      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({
          files: [file],
          title: 'QS Hub 匯出檔案',
          text: `共匯出 ${targetCards.length} 筆資料`,
        }).catch(err => {
          if (err.name !== 'AbortError') {
            console.warn("Share failed, falling back to download:", err);
            downloadFile(blob, fileName);
          }
        });
      } else {
        downloadFile(blob, fileName);
      }
    } catch (e) {
      console.error("Export Logic Error:", e);
    } finally {
      setIsExporting(false);
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案讀取失敗");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* 側邊欄 */}
      <aside 
        style={{ width: isMobile ? '100%' : `380px` }} 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r border-slate-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b bg-slate-50/50">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
               <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg">
                 <i className="fa-solid fa-bahai"></i>
               </div>
               <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest">QS HUB Pro</h2>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <button 
            onClick={() => handleExportAndShare()}
            disabled={cards.length === 0 || isExporting}
            className="w-full mb-6 bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-200 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-emerald-100 transition-all flex items-center justify-center gap-2 active:scale-95"
          >
            {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-share-nodes"></i>}
            {isExporting ? "匯出處理中..." : "匯出並分享全部資料"}
          </button>

          <div className="grid grid-cols-3 gap-2">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => handleExportAndShare('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => handleExportAndShare('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => handleExportAndShare('staff')} />
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      {/* 主工作區 */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-4 md:px-6 shrink-0 bg-white sticky top-0 z-50">
           <div className="flex items-center gap-3 overflow-hidden">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-500 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1 rounded-2xl overflow-x-auto no-scrollbar">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-10 custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full"><CameraScanner onCapture={async (b64) => { 
              const taskId = crypto.randomUUID();
              const res = await fetch(`data:image/jpeg;base64,${b64}`);
              filesMap.current.set(taskId, await res.blob());
              setTasks(prev => [...prev, { id: taskId, fileName: `掃描影像_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-sm p-12 border-2 border-dashed border-slate-200 rounded-[3rem] bg-white shadow-sm hover:border-indigo-300 transition-colors cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl text-indigo-500"></i>
                </div>
                <h3 className="text-xl font-black text-slate-800">上傳名片檔案</h3>
                <p className="text-slate-400 text-xs mt-3 leading-loose">支援多張圖片批次上傳辨識<br/>自動分類為 Employer / Academic / Staff</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID();
                    filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1 };
                  });
                  setTasks(prev => [...prev, ...newTasks]);
                  setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
