import { GoogleGenAI, Type } from "@google/genai";
import { ApiPlan } from "../types";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  plan: ApiPlan = 'free',
  retryCount = 0
): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // 免費方案使用 Flash，付費方案使用 Pro 提升精準度
  const model = plan === 'paid' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `請從這張名片中提取資訊，並將其格式化為「QS 資料填報」標準。

            【核心提取規則】：
            1. 核心欄位（如姓名、單位、職稱等）必須嚴格依照「名片上的原文」抓取。
            2. 翻譯規則：若原文為英文或非中文，請在 'translations' 物件中提供「精簡的中文對應翻譯字詞」。
               - ⚠ 警告：'translations' 欄位內「嚴禁」出現任何解釋、說明、中括號內容或推導過程。
            3. 分類標準：
               - 'academic': 大學教研人員。
               - 'staff': 大學行政支持人員。
               - 'employer': 企業雇主。

            【QS 欄位定義】：
            - prefix: 稱謂 (Mr, Ms, Dr, Prof 等)
            - firstName: 名 (First Name)
            - lastName: 姓 (Last Name)
            - title: 職稱 (Job Title / Position)
            - company: 單位名稱 (Institution / Company Name)
            - department: 部門 (Department)
            - subject: 學科領域 (Subject Area - 教研類必填)
            - industry: 產業 (Industry - 雇主類必填)
            - country: 國家/地區 (Country / Territory)

            【額外屬性】：
            - reasoning: 請在此欄位中說明分類理由（繁體中文）。

            請僅回傳 JSON 格式。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            source: { type: Type.STRING },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                subject: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "translations", "reasoning"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("503") && retryCount < 3) {
      await sleep(Math.pow(2, retryCount + 1) * 1000);
      return extractCardInfo(base64Image, mimeType, plan, retryCount + 1);
    }
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V3';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 3);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isExporting, setIsExporting] = useState(false);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };

    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handlePlanChange = (newPlan: ApiPlan) => {
    if (newPlan === 'paid' && plan === 'free') {
      if (window.confirm("切換至收費方案將使用高階 Pro 模型進行精準辨識。系統將開始計算進階點數，是否繼續？")) {
        setPlan(newPlan);
      }
    } else {
      setPlan(newPlan);
    }
  };

  const downloadFile = (blob: Blob, fileName: string) => {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  /**
   * 嚴格執行 QS HUB 格式
   */
  const handleExportAndShare = (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);

    if (targetCards.length === 0) {
      alert(`目前沒有 ${category} 的資料可供匯出`);
      return;
    }

    setIsExporting(true);

    try {
      const exportData = targetCards.map(c => {
        const baseData: any = {
          'Source': 'Business Card',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
        };

        if (category === 'employer') {
          // Employer 格式 (嚴格對齊圖片 2)
          return {
            ...baseData,
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Phone (Optional)': c.mobile || c.phone || '',
          };
        } else {
          // Academic/Staff 格式 (嚴格對齊圖片 1)
          return {
            ...baseData,
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Subject': c.subject || '',
            'Phone (Optional)': c.mobile || c.phone || '',
          };
        }
      });

      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, `QS_${category}`);

      const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
      const mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      const blob = new Blob([excelBuffer], { type: mimeType });
      const fileName = `QS_Hub_${category.toUpperCase()}_${new Date().toISOString().split('T')[0]}.xlsx`;
      const file = new File([blob], fileName, { type: mimeType });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({
          files: [file],
          title: `QS Hub ${category} 匯出`,
          text: `匯出 ${targetCards.length} 筆資料`,
        }).catch(err => {
          if (err.name !== 'AbortError') downloadFile(blob, fileName);
        });
      } else {
        downloadFile(blob, fileName);
      }
    } catch (e) {
      console.error("Export Error:", e);
    } finally {
      setIsExporting(false);
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案讀取失敗");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* 圖片放大 Lightbox */}
      {lightboxImage && (
        <div className="fixed inset-0 z-[200] bg-black/95 flex items-center justify-center p-4 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setLightboxImage(null)}>
           <button className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center text-2xl hover:bg-white/20 transition-colors">
              <i className="fa-solid fa-xmark"></i>
           </button>
           <img src={lightboxImage} className="max-w-full max-h-full rounded-lg shadow-2xl object-contain animate-in zoom-in-95 duration-300" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {/* 側邊欄 */}
      <aside 
        style={{ width: isMobile ? '100%' : `380px` }} 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r border-slate-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b bg-slate-50/50">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
               <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg">
                 <i className="fa-solid fa-bahai"></i>
               </div>
               <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest">QS HUB Pro</h2>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          {/* 方案切換區 */}
          <div className="flex bg-slate-100 p-1 rounded-xl mb-6 shadow-inner">
             <button onClick={() => handlePlanChange('free')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'free' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>免費功能</button>
             <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>收費功能</button>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => handleExportAndShare('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => handleExportAndShare('academic')} />
