{
  "name": "QS Hub Desktop Uploader",
  "description": "Professional desktop-style utility for uploading business cards and extracting data in QS Hub format using Gemini AI.",
  "requestFramePermissions": [
    "camera"
  ]
}

import { GoogleGenAI, Type } from "@google/genai";
import { ApiPlan } from "../types";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  plan: ApiPlan = 'free',
  retryCount = 0
): Promise<any> => {
  // 每次調用時重新初始化，以確保獲取透過 window.aistudio.openSelectKey() 選擇的最新的 API Key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // 根據方案選擇模型
  const model = plan === 'paid' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `你是一位專業的 QS 資料分析專家，請從名片中提取資訊並嚴格遵循「QS HUB」格式。

【重要規則】：
1. 必須以「名片上的原文」為主。不要擅自修改拼字或格式。
2. Industry (產業): 針對 Employer 類別，請填寫符合 QS 國際慣例的產業術語 (例如：Technology, Finance, Higher Education, Manufacturing, Healthcare, Engineering, Consulting 等)。若名片未直寫，請根據公司背景合理推論最貼切的 QS 產業類別。
3. 僅回傳 JSON 格式。

【欄位對應說明】：
- prefix: 稱謂 (Mr, Ms, Dr, Prof 等)
- firstName: 名
- lastName: 姓
- title: 職稱 (Academic 類對應 Job Title，Employer 類對應 Position)
- company: 單位名稱 (Academic 類對應 Institution，Employer 類對應 Company Name)
- department: 部門 (Department)
- subject: 學科領域 (Subject Area)
- industry: 產業 (符合 QS 規範之術語)
- country: 國家/地區 (Country or Territory)
- email: 電子郵件
- phone: 電話/手機 (Phone)
- category: 分類，僅限 'employer', 'academic', 'staff'。大學教職為 academic，大學行政為 staff，一般企業為 employer。
- reasoning: 繁體中文說明分類依據與產業判斷理由。

請嚴格執行。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            phone: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING }
          },
          required: ["firstName", "lastName", "title", "company", "category", "reasoning"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    // 如果是因為 API Key 問題，向上拋出錯誤
    if (errorMessage.includes("Requested entity was not found")) {
        throw new Error("API_KEY_NOT_FOUND");
    }
    if (errorMessage.includes("503") && retryCount < 3) {
      await sleep(Math.pow(2, retryCount + 1) * 1000);
      return extractCardInfo(base64Image, mimeType, plan, retryCount + 1);
    }
    throw error;
  }
};

import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    try {
      // 停止現有串流
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        // 確保手機端能自動播放
        videoRef.current.setAttribute('playsinline', 'true');
        videoRef.current.setAttribute('muted', 'true');

        // 監聽元數據載入完成
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Video play failed:", e));
          setIsReady(true);
          setIsLoading(false);
        };
      }
      setStream(mediaStream);
    } catch (err: any) {
      console.error("Camera Error:", err);
      setIsLoading(false);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("請允許相機存取權限。若在 LINE/FB 中，請點擊右上角使用 Safari/Chrome 開啟。");
      } else if (err.name === 'NotFoundError') {
        setError("找不到可用的鏡頭設備。");
      } else {
        setError(`無法啟動相機: ${err.message || '未知錯誤'}`);
      }
    }
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2rem] overflow-hidden relative shadow-2xl">
      {!isReady ? (
        <div className="p-8 text-center animate-in fade-in zoom-in duration-300">
          <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6 text-indigo-400">
             <i className={`fa-solid ${isLoading ? 'fa-circle-notch fa-spin' : 'fa-camera'} text-3xl`}></i>
          </div>

          {error ? (
            <div className="max-w-xs">
              <h3 className="text-white font-bold mb-2">啟動失敗</h3>
              <p className="text-slate-400 text-xs mb-6 leading-relaxed">{error}</p>
              <button onClick={startCamera} className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold">重新嘗試啟動</button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-lg mb-2">準備核對名片</h3>
              <p className="text-slate-400 text-xs mb-8">建議將名片水平放置於取景框內，並確保光線充足。</p>
              <button 
                onClick={startCamera}
                disabled={isLoading}
                className="w-full bg-white text-slate-900 py-4 rounded-2xl font-black shadow-xl disabled:opacity-50"
              >
                {isLoading ? '相機載入中...' : '立即開啟相機'}
              </button>
            </div>
          )}
        </div>
      ) : (
        <>
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="h-full w-full object-cover" 
          />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/30 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(0,0,0,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-400 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-400 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-400 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-400 translate-x-1 translate-y-1 rounded-br-lg"></div>
                <div className="absolute top-0 left-0 w-full h-0.5 bg-indigo-400/50 animate-[scan_3s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center">
            <button 
              onClick={capture}
              className="w-20 h-20 rounded-full bg-white border-8 border-white/20 flex items-center justify-center shadow-2xl active:scale-90 transition-transform"
            >
              <div className="w-14 h-14 rounded-full bg-indigo-600"></div>
            </button>
          </div>

          <button 
            onClick={() => {
              if (stream) stream.getTracks().forEach(t => t.stop());
              setIsReady(false);
              onClose();
            }}
            className="absolute top-6 left-6 w-10 h-10 bg-black/50 text-white rounded-full flex items-center justify-center"
          >
            <i className="fa-solid fa-arrow-left"></i>
          </button>
        </>
      )}
      <style>{`
        @keyframes scan {
          0% { top: 0%; }
          100% { top: 100%; }
        }
      `}</style>
    </div>
  );
};

export default CameraScanner;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 5);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isExporting, setIsExporting] = useState(false);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };

    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
  }, [selectedCardId]);

  /**
   * 切換 API 方案邏輯
   * 整合 window.aistudio 功能
   */
  const handlePlanChange = async (newPlan: ApiPlan) => {
    if (newPlan === 'paid') {
      // 檢查是否已有選擇的 API Key
      // @ts-ignore
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      if (!hasKey) {
        if (window.confirm("使用 Pro 高階功能需要設置您自己的 Google API Key (建議為 Paid Project)。是否現在開啟選擇視窗？")) {
           // @ts-ignore
           await window.aistudio?.openSelectKey();
           setPlan('paid');
        }
      } else {
        setPlan('paid');
      }
    } else {
      setPlan('free');
    }
  };

  const downloadFile = (blob: Blob, fileName: string) => {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  const handleExportAndShare = (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) {
      alert(`目前沒有 ${category} 的資料可供匯出`);
      return;
    }
    setIsExporting(true);

    try {
      const exportData = targetCards.map(c => {
        const baseData: any = {
          'Source': 'Business Card',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
        };

        if (category === 'employer') {
          return {
            ...baseData,
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Phone (Optional)': c.phone || c.mobile || '',
          };
        } else {
          return {
            ...baseData,
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Subject': c.subject || '',
            'Phone (Optional)': c.phone || c.mobile || '',
          };
        }
      });

      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, `QS_${category}`);

      const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
      const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const fileName = `QS_Hub_${category.toUpperCase()}_${new Date().toISOString().split('T')[0]}.xlsx`;
      const file = new File([blob], fileName, { type: blob.type });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({
          files: [file],
          title: `QS Hub ${category} 資料匯出`,
        }).catch(() => downloadFile(blob, fileName));
      } else {
        downloadFile(blob, fileName);
      }
    } catch (e) {
      console.error("Export Error:", e);
    } finally {
      setIsExporting(false);
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案讀取失敗");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      if (err.message === "API_KEY_NOT_FOUND") {
         alert("API Key 無效或未授權，請重新選擇有效的 Google API Key。");
         // @ts-ignore
         window.aistudio?.openSelectKey();
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* 側邊欄 */}
      <aside 
        style={{ width: isMobile ? '100%' : `380px` }} 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r border-slate-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b bg-slate-50/50">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
               <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg">
                 <i className="fa-solid fa-bahai"></i>
               </div>
               <div className="flex flex-col">
                 <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest">QS HUB Scanner</h2>
                 <span className="text-[8px] font-bold text-indigo-500 uppercase tracking-tighter">Version 1.0 Release</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="space-y-3 mb-6">
            <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner border border-slate-200">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'free' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>免費辨識</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>使用自定義 API</button>
            </div>
            <p className="text-[9px] text-slate-400 text-center font-bold px-2 leading-relaxed">
              {plan === 'paid' ? '✓ 當前使用自定義 API (Pro 模型)' : '* 免費版由系統分配資源 (Flash 模型)'}
            </p>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => handleExportAndShare('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => handleExportAndShare('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => handleExportAndShare('staff')} />
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden bg-slate-50/30">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      {/* 主工作區 */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-4 md:px-6 shrink-0 bg-white/80 backdrop-blur-md sticky top-0 z-50">
           <div className="flex items-center gap-3 overflow-hidden">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-500 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1 rounded-2xl overflow-x-auto no-scrollbar">
                <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批次上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="辨識狀態" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-address-card" label="資料核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {viewMode === 'camera' ? (
            <div className="h-full p-4 md:p-8"><CameraScanner onCapture={async (b64) => { 
              const taskId = crypto.randomUUID();
              const res = await fetch(`data:image/jpeg;base64,${b64}`);
              filesMap.current.set(taskId, await res.blob());
              setTasks(prev => [...prev, { id: taskId, fileName: `掃描影像_${new Date().toLocaleTimeString()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center p-4">
              <div className="w-full max-w-sm p-12 border-2 border-dashed border-slate-200 rounded-[3rem] bg-white shadow-2xl shadow-indigo-50 hover:border-indigo-300 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl text-indigo-500"></i>
                </div>
                <h3 className="text-xl font-black text-slate-800">上傳名片檔案</h3>
                <p className="text-slate-400 text-[10px] uppercase font-bold mt-3 leading-loose tracking-widest">
                  當前辨識模式：{plan === 'paid' ? '自定義 API (高精確 Pro)' : '系統預設 (快速 Flash)'}
                </p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID();
                    filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1, plan };
                  });
                  setTasks(prev => [...prev, ...newTasks]);
                  setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-2xl mx-auto space-y-4 p-4 md:p-10">
              <div className="flex items-center justify-between border-b pb-4">
                 <h2 className="font-black text-xl text-slate-800">辨識隊列 ({tasks.length})</h2>
              </div>
              <div className="space-y-2 overflow-y-auto custom-scrollbar max-h-[70vh]">
                {tasks.length === 0 ? <div className="py-20 text-center text-slate-300 italic">目前沒有任務，請透過掃描或上傳新增</div> : tasks.map(t => (
                  <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between text-xs shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex items-center gap-3 min-w-0">
                      <i className={`fa-solid ${t.status === 'completed' ? 'fa-circle-check text-emerald-500' : t.status === 'error' ? 'fa-triangle-exclamation text-red-500' : 'fa-circle-notch fa-spin text-indigo-400'}`}></i>
                      <span className="font-bold text-slate-600 truncate">{t.fileName}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`font-black text-[9px] uppercase tracking-widest px-2 py-0.5 rounded ${t.plan === 'paid' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{t.plan}</span>
                      <span className={`font-black uppercase tracking-tighter ${t.status === 'completed' ? 'text-emerald-500' : 'text-indigo-500'}`}>{t.status}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : selectedCard ? (
            <div className="h-full flex flex-col lg:flex-row overflow-hidden animate-in fade-in duration-500">
               {/* 左側：原文圖片核對 */}
               <div className="flex-1 bg-slate-100 flex flex-col p-6 overflow-hidden relative border-r border-slate-200">
                  <div className="mb-4 flex items-center justify-between">
                     <div className="flex items-center gap-3">
                       <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest bg-white px-3 py-1.5 rounded-full shadow-sm">名片原文核對</span>
