                     </div>
                     <div className="flex gap-2">
                        <button onClick={() => setRotation(r => r - 90)} title="向左旋轉" className="w-10 h-10 bg-white rounded-full shadow-sm hover:shadow-md transition-all flex items-center justify-center text-slate-500 active:scale-90"><i className="fa-solid fa-rotate-left"></i></button>
