                      style={{ transform: `rotate(${rotation}deg)` }} 
                     />
                  </div>
               </div>

               {/* 右側：資料區域 */}
               <div className="w-full lg:w-[480px] bg-white overflow-y-auto custom-scrollbar p-8 lg:p-10 space-y-8 shadow-2xl z-10 border-l border-slate-100">
                  <div className="border-b border-slate-100 pb-6">
                    <div className={`inline-block px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest mb-4 ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : 'bg-emerald-100 text-emerald-600'}`}>
                      {selectedCard.category}
                    </div>
                    <h1 className="text-3xl font-black text-slate-800 tracking-tight leading-none mb-2">
                      {[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}
                    </h1>
                    <p className="text-slate-500 font-bold text-lg">{selectedCard.title}</p>
                  </div>

                  <div className="space-y-6">
                    <DetailItem label="單位 (Original Institution / Company Name)" value={selectedCard.company} />
                    <DetailItem label="Email (原文)" value={selectedCard.email} />
                    <DetailItem label="部門 (Department)" value={selectedCard.department} />
                    {selectedCard.category === 'employer' ? (
                      <DetailItem label="產業 (Industry - 符合 QS 規範)" value={selectedCard.industry} />
                    ) : (
                      <DetailItem label="學科領域 (Subject Area)" value={selectedCard.subject} />
                    )}
                    <DetailItem label="國家/地區 (Country or Territory)" value={selectedCard.country} />
                    <DetailItem label="聯絡電話 (Phone / Mobile)" value={selectedCard.phone} />
                  </div>

                  <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 shadow-sm">
                    <div className="flex items-center gap-2 mb-3">
                       <i className="fa-solid fa-robot text-indigo-400 text-xs"></i>
                       <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">AI 分類邏輯判斷</h4>
                    </div>
                    <p className="text-xs text-slate-500 leading-relaxed italic">「{selectedCard.reasoning}」</p>
                  </div>

                  <div className="pt-6 border-t border-slate-50 text-center space-y-2">
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-relaxed">
                      請核對左右資訊是否完全一致<br/>
                      若需下載 Excel，請使用左側分類標籤按鈕
                    </p>
                  </div>
               </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-200">
               <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                 <i className="fa-solid fa-magnifying-glass text-4xl"></i>
               </div>
               <p className="font-black text-xs uppercase tracking-widest">請從左側列表選擇卡片或上傳新文件</p>
            </div>
          )}
        </div>
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 z-[90] backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}
    </div>
  );
};

const DetailItem = ({ label, value }: { label: string, value?: string }) => (
  <div className="group space-y-1">
    <label className="text-[10px] font-black text-slate-300 uppercase tracking-widest block transition-colors group-hover:text-indigo-400">{label}</label>
    <div className="font-black text-slate-700 text-base border-b border-slate-100 pb-2 break-words group-hover:border-indigo-100 transition-all">{value || '---'}</div>
  </div>
);

const CategoryTab = ({ color, label, count, onExport }: any) => (
