import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const startCamera = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("您的瀏覽器不支援相機存取，或未處於安全連線 (HTTPS) 環境下。");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // 停止現有串流
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      // 放寬限制以增加行動裝置成功率
      const constraints: MediaStreamConstraints = {
        video: {
          facingMode: { ideal: 'environment' },
          // 移除嚴格的解析度要求，改用 ideal
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);

      if (videoRef.current) {
        const video = videoRef.current;

        // 核心修正：先綁定監聽器再賦值 srcObject
        const onMetadataLoaded = async () => {
          try {
            await video.play();
            setIsReady(true);
            setIsLoading(false);
          } catch (e) {
            console.error("Video play failed:", e);
            // 某些瀏覽器可能需要使用者點擊才能播放，即使 muted
            setIsLoading(false);
            setIsReady(true); 
          }
        };

        video.onloadedmetadata = onMetadataLoaded;
        video.srcObject = mediaStream;

        // 強制執行屬性
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;
      }
      setStream(mediaStream);
    } catch (err: any) {
      console.error("Camera Error:", err);
      setIsLoading(false);

      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("相機權限遭拒。請前往瀏覽器設定允許存取，或更換 Chrome/Safari 開啟。");
      } else if (err.name === 'OverconstrainedError') {
        setError("相機硬體不支援要求的解析度。");
      } else if (err.name === 'NotFoundError') {
        setError("找不到相機設備。");
      } else {
        setError(`無法啟動相機: ${err.message || '未知錯誤'}`);
      }
    }
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2rem] overflow-hidden relative shadow-2xl min-h-[400px]">
      {!isReady ? (
        <div className="p-8 text-center animate-in fade-in zoom-in duration-300 w-full flex flex-col items-center">
          <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mb-6 text-indigo-400">
             {isLoading ? (
               <i className="fa-solid fa-circle-notch fa-spin text-3xl"></i>
             ) : (
               <i className="fa-solid fa-camera text-3xl"></i>
             )}
          </div>

          {error ? (
            <div className="max-w-xs">
              <h3 className="text-white font-bold mb-2">相機啟動失敗</h3>
              <p className="text-slate-400 text-xs mb-6 leading-relaxed">{error}</p>
              <button 
                onClick={startCamera} 
                className="w-full bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-transform"
              >
                重新整理並嘗試啟動
              </button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-lg mb-2">準備核對名片</h3>
              <p className="text-slate-400 text-xs mb-8">請將名片水平放置於取景框內，<br/>確保光線充足、無反光。</p>
              <button 
                onClick={startCamera}
                disabled={isLoading}
                className="w-full bg-white text-slate-900 py-4 rounded-2xl font-black shadow-xl disabled:opacity-50 transition-all active:scale-95"
              >
                {isLoading ? '相機載入中...' : '開啟相機進行掃描'}
              </button>
            </div>
          )}
        </div>
      ) : (
        <>
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="h-full w-full object-cover" 
          />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/30 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(0,0,0,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-400 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-400 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-400 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-400 translate-x-1 translate-y-1 rounded-br-lg"></div>
                <div className="absolute top-0 left-0 w-full h-0.5 bg-indigo-400/50 animate-[scan_3s_infinite_linear]"></div>
