import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // 對焦相關狀態
  const [focusCapabilities, setFocusCapabilities] = useState<{
    canManual: boolean;
    min?: number;
    max?: number;
    step?: number;
  }>({ canManual: false });
  const [focusMode, setFocusMode] = useState<'continuous' | 'manual'>('continuous');
  const [focusDistance, setFocusDistance] = useState<number>(0);
  const [tapPosition, setTapPosition] = useState<{ x: number, y: number } | null>(null);

  const startCamera = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("您的瀏覽器不支援相機功能，或未處於 HTTPS 安全連線環境。");
      return;
    }

    setIsLoading(true);
    setError(null);

    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }

    const constraintOptions = [
      {
        video: { 
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        }
      },
      {
        video: { facingMode: 'environment' }
      },
      {
        video: true
      }
    ];

    let lastError: any = null;
    let mediaStream: MediaStream | null = null;

    for (const constraints of constraintOptions) {
      try {
        mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
        if (mediaStream) break;
      } catch (err) {
        lastError = err;
        continue;
      }
    }

    if (!mediaStream) {
      setIsLoading(false);
      setError(lastError?.name === 'NotFoundError' ? "找不到相機設備。" : `啟動失敗: ${lastError?.message}`);
      return;
    }

    const track = mediaStream.getVideoTracks()[0];
    if (track) {
      // 偵測對焦能力
      const capabilities = (track as any).getCapabilities?.() || {};
      const focusModes = capabilities.focusMode || [];
      const canManual = focusModes.includes('manual');

      if (canManual && capabilities.focusDistance) {
        setFocusCapabilities({
          canManual: true,
          min: capabilities.focusDistance.min,
          max: capabilities.focusDistance.max,
          step: capabilities.focusDistance.step,
        });
        setFocusDistance(capabilities.focusDistance.min);
      }
    }

    try {
      if (videoRef.current) {
        const video = videoRef.current;
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;
        video.onloadedmetadata = async () => {
          try {
            await video.play();
            setIsReady(true);
            setIsLoading(false);
          } catch (e) {
            setIsReady(true);
            setIsLoading(false);
          }
        };
        video.srcObject = mediaStream;
      }
      setStream(mediaStream);
    } catch (err: any) {
      setIsLoading(false);
      setError(`相機配置失敗: ${err.message}`);
    }
  };

  const handleApplyFocus = async (mode: 'continuous' | 'manual', distance?: number) => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    if (!track) return;

    try {
      const constraints: any = {
        advanced: [{ focusMode: mode }]
      };
      if (mode === 'manual' && distance !== undefined) {
        constraints.advanced[0].focusDistance = distance;
      }
      await (track as any).applyConstraints(constraints);
      setFocusMode(mode);
    } catch (e) {
      console.warn("Failed to apply focus constraints", e);
    }
  };

  const handleScreenTap = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isReady) return;
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const x = ('touches' in e) ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const y = ('touches' in e) ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    setTapPosition({ x: x - rect.left, y: y - rect.top });
    setTimeout(() => setTapPosition(null), 1000);

    // 觸發重新對焦：先切換到手動再切回自動，或直接觸發對焦 (視硬體而定)
    handleApplyFocus('continuous');
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
