import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  // 對焦相關狀態
  const [focusCapabilities, setFocusCapabilities] = useState<{
    canManual: boolean;
    min?: number;
    max?: number;
    step?: number;
  }>({ canManual: false });
  const [focusMode, setFocusMode] = useState<'continuous' | 'manual'>('continuous');
  const [focusDistance, setFocusDistance] = useState<number>(0);
  const [tapPosition, setTapPosition] = useState<{ x: number, y: number } | null>(null);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        track.stop();
        console.log(`Track ${track.label} stopped.`);
      });
      setStream(null);
    }
  };

  const startCamera = async () => {
    // 檢查安全連線
    if (window.location.protocol !== 'https:' && window.location.hostname !== 'localhost') {
      setError("相機功能僅能在安全連線 (HTTPS) 下運作。請檢查網址或聯絡管理員。");
      return;
    }

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("您的瀏覽器不支援現代相機 API。請更換為 Chrome 或 Safari。");
      return;
    }

    setIsLoading(true);
    setError(null);
    setStatusMsg("正在偵測攝影機...");

    stopTracks();

    // 依序嘗試的約束條件 (從理想型到基本型)
    const constraintList = [
      { video: { facingMode: { ideal: 'environment' }, width: { ideal: 1920 }, height: { ideal: 1080 } }, audio: false },
      { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false },
      { video: { facingMode: 'user' }, audio: false }, // 退而求其次嘗試前鏡頭
      { video: true, audio: false } // 最後手段
    ];

    let mediaStream: MediaStream | null = null;
    let lastError: any = null;

    for (let i = 0; i < constraintList.length; i++) {
      try {
        setStatusMsg(`嘗試連線鏡頭 (模式 ${i + 1})...`);
        mediaStream = await navigator.mediaDevices.getUserMedia(constraintList[i]);
        if (mediaStream) {
          console.log("Stream obtained with constraints:", constraintList[i]);
          break;
        }
      } catch (err: any) {
        lastError = err;
        console.warn(`Constraint set ${i} failed:`, err.name);
      }
    }

    if (!mediaStream) {
      setIsLoading(false);
      if (lastError?.name === 'NotAllowedError' || lastError?.name === 'PermissionDeniedError') {
        setError("權限遭拒：請在瀏覽器設定中允許此網頁存取相機。");
      } else if (lastError?.name === 'NotFoundError') {
        setError("找不到鏡頭設備：請確認裝置攝影機運作正常且未被其他 App 佔用。");
      } else {
        setError(`無法啟動相機: ${lastError?.message || '未知硬體錯誤'}`);
      }
      return;
    }

    setStream(mediaStream);

    try {
      if (videoRef.current) {
        const video = videoRef.current;

        // 偵測對焦能力
        const track = mediaStream.getVideoTracks()[0];
        if (track && (track as any).getCapabilities) {
          try {
            const capabilities = (track as any).getCapabilities() || {};
            const focusModes = capabilities.focusMode || [];
            const canManual = focusModes.includes('manual');
            if (canManual && capabilities.focusDistance) {
              setFocusCapabilities({
                canManual: true,
                min: capabilities.focusDistance.min,
                max: capabilities.focusDistance.max,
                step: capabilities.focusDistance.step,
              });
              setFocusDistance(capabilities.focusDistance.min);
            }
          } catch (e) { console.warn("Focus capabilities detection failed", e); }
        }

        // 重要：確保 video 屬性正確，防止行動端無法播放
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;

        video.onloadedmetadata = async () => {
          setStatusMsg("正在初始化畫面...");
          try {
            await video.play();
            // 在確保有影像寬度後才正式啟動 UI
            if (video.videoWidth > 0) {
              setIsReady(true);
              setIsLoading(false);
            } else {
              // 有些 Android 設備需要一點延遲
              setTimeout(() => {
                setIsReady(true);
                setIsLoading(false);
              }, 500);
            }
          } catch (e) {
            console.error("Video play failed:", e);
            setError("相機啟動成功但無法播放畫面。請嘗試重新整理。");
            setIsLoading(false);
          }
        };

        video.srcObject = mediaStream;
      }
    } catch (err: any) {
      setIsLoading(false);
      setError(`視訊配置錯誤: ${err.message}`);
    }
  };

  const handleApplyFocus = async (mode: 'continuous' | 'manual', distance?: number) => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    if (!track || !(track as any).applyConstraints) return;

    try {
      const constraints: any = { advanced: [{ focusMode: mode }] };
      if (mode === 'manual' && distance !== undefined) {
        constraints.advanced[0].focusDistance = distance;
      }
      await (track as any).applyConstraints(constraints);
      setFocusMode(mode);
    } catch (e) { console.warn("Failed to apply focus constraints", e); }
  };

  const handleScreenTap = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isReady) return;
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const x = ('touches' in e) ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const y = ('touches' in e) ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    setTapPosition({ x: x - rect.left, y: y - rect.top });
    setTimeout(() => setTapPosition(null), 1000);
    handleApplyFocus('continuous');
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2rem] overflow-hidden relative shadow-2xl min-h-[400px]">
      {!isReady ? (
        <div className="p-8 text-center animate-in fade-in zoom-in duration-300 w-full flex flex-col items-center">
          <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mb-6 text-indigo-400">
             {isLoading ? <i className="fa-solid fa-circle-notch fa-spin text-3xl"></i> : <i className="fa-solid fa-camera text-3xl"></i>}
          </div>
          {error ? (
            <div className="max-w-xs">
              <h3 className="text-white font-bold mb-2">無法啟動掃描器</h3>
              <p className="text-slate-400 text-[11px] mb-6 leading-relaxed">{error}</p>
              <button onClick={startCamera} className="w-full bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold active:scale-95 transition-transform shadow-lg shadow-indigo-500/20">
                重試啟動
              </button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-lg mb-2">準備掃描名片</h3>
              <p className="text-slate-400 text-xs mb-8 text-center leading-relaxed">
                {isLoading ? statusMsg : "系統將啟動後置鏡頭。請確保環境光線充足並對準名片。"}
              </p>
              {!isLoading && (
                <button onClick={startCamera} className="w-full bg-white text-slate-900 py-4 rounded-2xl font-black shadow-xl active:scale-95 transition-all">
                  點擊開啟相機
                </button>
              )}
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="h-full w-full relative" onClick={handleScreenTap} onTouchStart={handleScreenTap}>
            <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-cover" />
            {tapPosition && (
              <div className="absolute w-16 h-16 border-2 border-indigo-400 rounded-full animate-ping pointer-events-none" style={{ top: tapPosition.y - 32, left: tapPosition.x - 32 }} />
            )}
            {tapPosition && (
              <div className="absolute w-12 h-12 border border-white/50 rounded-full pointer-events-none" style={{ top: tapPosition.y - 24, left: tapPosition.x - 24 }} />
            )}
          </div>

          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/30 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(0,0,0,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-400 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-400 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-400 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-400 translate-x-1 translate-y-1 rounded-br-lg"></div>
                <div className="absolute top-0 left-0 w-full h-0.5 bg-indigo-400/50 animate-[scan_3s_infinite_linear]"></div>
             </div>
          </div>

          {focusCapabilities.canManual && (
            <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col items-center gap-4 bg-black/40 backdrop-blur-md p-3 rounded-full border border-white/10">
              <button 
                onClick={(e) => { e.stopPropagation(); handleApplyFocus(focusMode === 'continuous' ? 'manual' : 'continuous'); }}
                className={`w-10 h-10 rounded-full flex items-center justify-center text-[10px] font-black transition-all ${focusMode === 'manual' ? 'bg-indigo-600 text-white' : 'bg-white/20 text-white'}`}
              >
                {focusMode === 'manual' ? 'MF' : 'AF'}
              </button>
              <div className="relative h-48 flex flex-col items-center group">
                <input 
                  type="range"
                  min={focusCapabilities.min}
                  max={focusCapabilities.max}
                  step={focusCapabilities.step}
                  value={focusDistance}
                  onChange={(e) => {
                    const val = parseFloat(e.target.value);
                    setFocusDistance(val);
                    handleApplyFocus('manual', val);
                  }}
                  className="h-40 w-1 accent-indigo-500 appearance-none bg-white/20 rounded-full vertical-slider"
                  style={{ writingMode: 'bt-lr', appearance: 'slider-vertical' } as any}
                />
              </div>
              <i className="fa-solid fa-expand text-white/40 text-[10px]"></i>
            </div>
          )}

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-8">
            <button onClick={capture} className="w-20 h-20 rounded-full bg-white border-8 border-white/20 flex items-center justify-center shadow-2xl active:scale-90 transition-transform">
              <div className="w-14 h-14 rounded-full bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.5)]"></div>
            </button>
          </div>

          <button onClick={() => { stopTracks(); onClose(); }} className="absolute top-6 left-6 w-10 h-10 bg-black/50 text-white rounded-full flex items-center justify-center backdrop-blur-md">
            <i className="fa-solid fa-arrow-left"></i>
          </button>

          <div className="absolute top-6 right-6 px-3 py-1 bg-black/30 backdrop-blur-md rounded-full text-[9px] font-black text-white/70 uppercase tracking-widest border border-white/5">
             {focusMode === 'manual' ? 'Manual Focus' : 'Auto Focus'}
          </div>
        </>
      )}
      <style>{`
