            <div className="flex items-center gap-2">
               <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg">
                 <i className="fa-solid fa-bahai"></i>
               </div>
               <div className="flex flex-col">
                 <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest">QS HUB Scanner</h2>
                 <span className="text-[8px] font-bold text-indigo-500 uppercase tracking-tighter">Version 1.1 Stable</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="space-y-3 mb-6">
            <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner border border-slate-200">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'free' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>免費辨識</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>自定義 API</button>
            </div>
            <p className="text-[9px] text-slate-400 text-center font-bold px-2 leading-relaxed">
              {plan === 'paid' ? '✓ 使用自定義 API (Pro 模型)' : '* 免費版資源共用 (Flash 模型)'}
            </p>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => handleExportAndShare('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => handleExportAndShare('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => handleExportAndShare('staff')} />
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden bg-slate-50/30">
