import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  // 對焦相關狀態
  const [focusCapabilities, setFocusCapabilities] = useState<{
    canManual: boolean;
    min?: number;
    max?: number;
    step?: number;
  }>({ canManual: false });
  const [focusMode, setFocusMode] = useState<'continuous' | 'manual'>('continuous');
  const [focusDistance, setFocusDistance] = useState<number>(0);
  const [tapPosition, setTapPosition] = useState<{ x: number, y: number } | null>(null);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
  };

  const startCamera = async () => {
    // 優先檢查 API 是否存在
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("您的瀏覽器不支援相機 API。請確保使用 Chrome、Safari 或 Edge 並檢查權限設定。");
      return;
    }

    setIsLoading(true);
    setError(null);
    setStatusMsg("正在喚醒相機...");

    stopTracks();

    // 依序嘗試的約束條件 (由強至弱)
    const constraintOptions = [
      { video: { facingMode: { ideal: 'environment' }, width: { ideal: 1920 }, height: { ideal: 1080 } }, audio: false },
      { video: { facingMode: 'environment' }, audio: false },
      { video: { facingMode: 'user' }, audio: false },
      { video: true, audio: false }
    ];

    let mediaStream: MediaStream | null = null;
    let lastError: any = null;

    for (let i = 0; i < constraintOptions.length; i++) {
      try {
        setStatusMsg(`正在建立連線 (${i + 1}/${constraintOptions.length})...`);
        mediaStream = await navigator.mediaDevices.getUserMedia(constraintOptions[i]);
        if (mediaStream) break;
      } catch (err: any) {
        lastError = err;
        console.warn(`Constraint set ${i} failed:`, err.name);
      }
    }

    if (!mediaStream) {
      setIsLoading(false);
      if (lastError?.name === 'NotAllowedError' || lastError?.name === 'PermissionDeniedError') {
        setError("權限遭拒：請點擊網址旁的「鎖頭」圖示，並允許存取相機。");
      } else if (lastError?.name === 'NotFoundError') {
        setError("找不到鏡頭：請確認攝影機未被其他應用程式佔用。");
      } else if (!window.isSecureContext) {
        setError("安全性錯誤：相機功能需要 HTTPS 安全連線環境。");
      } else {
        setError(`啟動失敗 (${lastError?.name}): ${lastError?.message || '未知錯誤'}`);
      }
      return;
    }

    setStream(mediaStream);

    try {
      if (videoRef.current) {
        const video = videoRef.current;

        // 偵測對焦能力
        const track = mediaStream.getVideoTracks()[0];
        if (track && (track as any).getCapabilities) {
          try {
            const capabilities = (track as any).getCapabilities() || {};
            const focusModes = capabilities.focusMode || [];
            if (focusModes.includes('manual') && capabilities.focusDistance) {
              setFocusCapabilities({
                canManual: true,
                min: capabilities.focusDistance.min,
                max: capabilities.focusDistance.max,
                step: capabilities.focusDistance.step,
              });
              setFocusDistance(capabilities.focusDistance.min);
            }
          } catch (e) {}
        }

        // 設定行動端必備屬性
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;

        video.onloadedmetadata = async () => {
          setStatusMsg("準備畫面中...");
          try {
            await video.play();
            // 確保影像已真正開始呈現
            if (video.videoWidth > 0) {
              setIsReady(true);
              setIsLoading(false);
            } else {
              // 補救延遲
              setTimeout(() => {
                setIsReady(true);
                setIsLoading(false);
              }, 800);
            }
          } catch (e) {
            console.error("Play failed:", e);
            setError("相機啟動成功但無法顯示畫面。請嘗試重新點擊開啟。");
            setIsLoading(false);
          }
        };

        video.srcObject = mediaStream;
      }
    } catch (err: any) {
      setIsLoading(false);
      setError(`配置錯誤: ${err.message}`);
    }
  };

  const handleApplyFocus = async (mode: 'continuous' | 'manual', distance?: number) => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    if (!track || !(track as any).applyConstraints) return;
    try {
      const constraints: any = { advanced: [{ focusMode: mode }] };
      if (mode === 'manual' && distance !== undefined) {
        constraints.advanced[0].focusDistance = distance;
      }
      await (track as any).applyConstraints(constraints);
      setFocusMode(mode);
    } catch (e) {}
  };

  const handleScreenTap = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isReady) return;
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const x = ('touches' in e) ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const y = ('touches' in e) ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    setTapPosition({ x: x - rect.left, y: y - rect.top });
    setTimeout(() => setTapPosition(null), 1000);
    handleApplyFocus('continuous');
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
