import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  const [focusCapabilities, setFocusCapabilities] = useState<{
    canManual: boolean;
    min?: number;
    max?: number;
    step?: number;
  }>({ canManual: false });
  const [focusMode, setFocusMode] = useState<'continuous' | 'manual'>('continuous');
  const [focusDistance, setFocusDistance] = useState<number>(0);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
  };

  const startCamera = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("您的瀏覽器版本過舊，不支援相機 API。請更換為最新版 Chrome 或 Safari。");
      return;
    }

    setIsLoading(true);
    setError(null);
    setStatusMsg("正在喚醒相機系統...");
    stopTracks();

    try {
      // 策略：先用最簡單的約束取得權限，避免在特定環境下因為 ideal 解析度而掛起
      setStatusMsg("請求存取權限中...");

      // 設置超時機制，防止 getUserMedia 沒反應
      const getUserMediaWithTimeout = (constraints: MediaStreamConstraints, timeout: number) => {
        return Promise.race([
          navigator.mediaDevices.getUserMedia(constraints),
          new Promise<null>((_, reject) => 
            setTimeout(() => reject(new Error("TIMEOUT")), timeout)
          )
        ]);
      };

      // 1. 先用最基本的視訊請求來觸發瀏覽器的權限詢問
      let mediaStream: MediaStream | null = null;
      try {
        mediaStream = await getUserMediaWithTimeout({ video: true, audio: false }, 8000) as MediaStream;
      } catch (e: any) {
        if (e.message === "TIMEOUT") {
          throw new Error("相機回應超時。請確認沒有其他 App 正在使用相機，或嘗試重新整理網頁。");
        }
        // 如果基本請求失敗，可能是真的沒設備或權限被拒
        throw e;
      }

      // 2. 成功取得基本串流後，嘗試切換到後置鏡頭 (環境模式)
      setStatusMsg("正在優化影像品質...");
      const tracks = mediaStream.getVideoTracks();
      if (tracks.length > 0) {
        try {
          // 嘗試套用環境鏡頭約束
          await tracks[0].applyConstraints({
            facingMode: 'environment',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          });
        } catch (e) {
          console.warn("無法切換到後置鏡頭，將使用預設設備。");
        }
      }

      setStream(mediaStream);

      if (videoRef.current) {
        const video = videoRef.current;
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;

        video.onloadedmetadata = async () => {
          try {
            await video.play();
            // 偵測對焦能力
            const activeTrack = mediaStream!.getVideoTracks()[0];
            if (activeTrack && (activeTrack as any).getCapabilities) {
              const caps = (activeTrack as any).getCapabilities();
              if (caps.focusMode?.includes('manual')) {
                setFocusCapabilities({
                  canManual: true,
                  min: caps.focusDistance?.min || 0,
                  max: caps.focusDistance?.max || 10,
                  step: caps.focusDistance?.step || 0.1,
                });
              }
            }
            setIsReady(true);
            setIsLoading(false);
          } catch (playError) {
            setError("影像播放被攔截。請點擊畫面中的播放按鈕或重新開啟。");
            setIsLoading(false);
          }
        };
        video.srcObject = mediaStream;
      }

    } catch (err: any) {
      console.error("Camera error:", err);
      setIsLoading(false);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("權限不足：請在瀏覽器設定中允許此網頁使用相機。");
      } else if (err.name === 'NotFoundError') {
        setError("找不到相機設備。");
      } else if (err.message === "TIMEOUT") {
        setError("連線逾時：相機沒有回應，請重新點擊並留意瀏覽器的權限彈窗。");
      } else {
        setError(err.message || "發生未知錯誤，請重試。");
      }
    }
  };

  const handleApplyFocus = async (mode: 'continuous' | 'manual', distance?: number) => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    if (!track || !(track as any).applyConstraints) return;
    try {
      const constraints: any = { advanced: [{ focusMode: mode }] };
      if (mode === 'manual' && distance !== undefined) {
        constraints.advanced[0].focusDistance = distance;
      }
      await (track as any).applyConstraints(constraints);
      setFocusMode(mode);
    } catch (e) {}
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-[#0f172a] rounded-[2rem] overflow-hidden relative shadow-2xl min-h-[450px] border border-white/5">
      {!isReady ? (
        <div className="p-10 text-center w-full flex flex-col items-center">
          <div className="w-24 h-24 bg-indigo-500/10 rounded-[2.5rem] flex items-center justify-center mb-10 text-indigo-400">
             {isLoading ? (
                <i className="fa-solid fa-spinner fa-spin text-4xl"></i>
             ) : (
                <i className="fa-solid fa-camera-retro text-4xl"></i>
             )}
          </div>

          {error ? (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-white font-black text-xl mb-4">糟糕！遇到問題了</h3>
              <p className="text-slate-400 text-xs mb-10 leading-relaxed max-w-[280px]">
                {error}
                <br/><br/>
                <span className="text-indigo-400/80">提示：若持續失敗，建議使用「批次上傳」並從相簿選擇照片。</span>
              </p>
              <button 
                onClick={startCamera} 
                className="w-full bg-indigo-600 text-white py-4 px-10 rounded-2xl font-black shadow-xl shadow-indigo-600/20 active:scale-95 transition-all mb-4"
              >
                再次嘗試開啟
              </button>
              <button 
                onClick={onClose}
                className="text-slate-500 text-[11px] font-bold uppercase tracking-widest"
              >
                返回主選單
              </button>
            </div>
          ) : (
            <div className="animate-in fade-in duration-700">
              <h3 className="text-white font-black text-2xl mb-4">即時掃描模式</h3>
              <p className="text-slate-400 text-xs mb-12 leading-relaxed max-w-[260px]">
                {isLoading ? statusMsg : "點擊下方按鈕以啟動攝影機。系統將自動辨識名片資訊並分類。"}
              </p>
              {!isLoading && (
                <button 
                  onClick={startCamera} 
                  className="bg-white text-slate-900 py-5 px-12 rounded-[2rem] font-black shadow-2xl active:scale-95 transition-all text-lg flex items-center gap-3"
                >
                  <i className="fa-solid fa-power-off text-indigo-500"></i>
                  啟動攝影機
                </button>
              )}
            </div>
          )}
        </div>
      ) : (
        <>
          <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-cover" />

          <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/20 rounded-3xl relative">
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500 -translate-x-1.5 -translate-y-1.5 rounded-tl-xl"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500 translate-x-1.5 -translate-y-1.5 rounded-tr-xl"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500 -translate-x-1.5 translate-y-1.5 rounded-bl-xl"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500 translate-x-1.5 translate-y-1.5 rounded-br-xl"></div>

                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent animate-[scan_2s_infinite_linear] shadow-[0_0_15px_rgba(129,140,248,0.5)]"></div>
             </div>
             <p className="mt-8 text-white/40 text-[10px] font-black uppercase tracking-[0.3em] bg-black/40 px-4 py-1.5 rounded-full backdrop-blur-md">
                Align card within frame
             </p>
          </div>

          <div className="absolute bottom-12 left-0 right-0 flex justify-center">
            <button 
              onClick={capture} 
              className="w-24 h-24 rounded-full bg-white/10 border-[6px] border-white/20 p-1 active:scale-90 transition-all group"
            >
              <div className="w-full h-full rounded-full bg-white flex items-center justify-center shadow-[0_0_40px_rgba(255,255,255,0.3)]">
                <i className="fa-solid fa-bolt-lightning text-indigo-600 text-2xl"></i>
              </div>
            </button>
          </div>

          <button 
            onClick={() => { stopTracks(); onClose(); }} 
            className="absolute top-8 left-8 w-12 h-12 bg-black/50 text-white rounded-2xl flex items-center justify-center backdrop-blur-xl border border-white/10 active:scale-90 transition-all"
          >
            <i className="fa-solid fa-xmark text-lg"></i>
          </button>

          {focusCapabilities.canManual && (
            <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col items-center gap-6 bg-black/50 backdrop-blur-xl p-4 rounded-full border border-white/10">
              <button 
                onClick={() => handleApplyFocus(focusMode === 'continuous' ? 'manual' : 'continuous')}
                className={`w-12 h-12 rounded-full flex items-center justify-center text-[10px] font-black transition-all ${focusMode === 'manual' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/10 text-white/40'}`}
              >
                {focusMode === 'manual' ? 'MF' : 'AF'}
              </button>
              <input 
                type="range"
                min={focusCapabilities.min}
                max={focusCapabilities.max}
                step={focusCapabilities.step}
                value={focusDistance}
                onChange={(e) => {
                  const val = parseFloat(e.target.value);
                  setFocusDistance(val);
                  handleApplyFocus('manual', val);
                }}
                className="h-32 w-1 accent-indigo-400 bg-white/20 rounded-full cursor-pointer appearance-none"
                style={{ writingMode: 'bt-lr', appearance: 'slider-vertical' } as any}
              />
            </div>
