      setError("瀏覽器不支援相機存取，請切換至 Chrome 或 Safari。");
      return;
    }

    setIsLoading(true);
    setError(null);
    setStatusMsg("正在開啟攝影機...");
    stopTracks();

    try {
      let mediaStream: MediaStream | null = null;

      // 嘗試 1: 直接請求後置鏡頭 (最穩定的基礎設定)
      try {
        mediaStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: "environment" }, 
          audio: false 
        });
      } catch (e) {
        console.warn("後置鏡頭啟動失敗，嘗試預設鏡頭...");
        // 嘗試 2: 降級至任何可用鏡頭
        mediaStream = await navigator.mediaDevices.getUserMedia({ 
          video: true, 
          audio: false 
        });
      }

      if (!mediaStream) throw new Error("無法取得視訊串流");

      setStream(mediaStream);

      if (videoRef.current) {
        const video = videoRef.current;

        // 強制行動端必備屬性
        video.setAttribute('playsinline', 'true');
        video.setAttribute('muted', 'true');
        video.muted = true;

        // 使用更穩定的監聽組合
        const handlePlay = () => {
          setStatusMsg("畫面已就緒");
          // 給予微小延遲確保硬體緩衝完成
          setTimeout(() => {
            setIsReady(true);
            setIsLoading(false);
          }, 300);
        };

        video.onplaying = handlePlay;

        video.srcObject = mediaStream;

        // 手動觸發播放 (應對部分瀏覽器的自動播放限制)
        try {
          await video.play();
        } catch (playErr) {
          console.error("Video play triggered error:", playErr);
          // 如果自動播放被擋，至少讓 UI 顯示出來
          setIsReady(true);
          setIsLoading(false);
        }
      }

    } catch (err: any) {
      console.error("Camera entry error:", err);
      setIsLoading(false);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("權限不足：請允許瀏覽器存取相機。");
      } else if (err.name === 'NotFoundError') {
        setError("設備錯誤：找不到可用的相機。");
      } else {
        setError("啟動超時或失敗，請檢查權限或重新整理頁面。");
      }
    }
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // 使用視訊實際的原始解析度
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
        stopTracks();
      }
    }
