import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("瀏覽器不支援相機功能，請更換至 Chrome 或 Safari。");
      return;
    }

    setIsLoading(true);
    setError(null);
    stopTracks();

    try {
      // 請求最基礎的後置鏡頭設定
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: "environment",
          width: { ideal: 1280 },
          height: { ideal: 720 }
        }, 
        audio: false 
      });

      setStream(mediaStream);

      // 重要：直接操作 video 標籤
      if (videoRef.current) {
        const video = videoRef.current;
        video.srcObject = mediaStream;

        // 監聽元數據載入
        video.onloadedmetadata = () => {
          video.play().then(() => {
            setIsReady(true);
            setIsLoading(false);
          }).catch(err => {
            console.error("Play failed:", err);
            // 即使 play() 失敗（例如自動播放政策限制），也讓 UI 顯示出來讓使用者點擊
            setIsReady(true);
            setIsLoading(false);
          });
        };
      } else {
        throw new Error("找不到影像播放元件");
      }

    } catch (err: any) {
      console.error("Camera Error:", err);
      setIsLoading(false);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("權限不足：請允許相機存取。");
      } else {
        setError("相機啟動失敗，請確認沒有其他應用程式正在佔用。");
      }
    }
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-[#0f172a] rounded-[2rem] overflow-hidden relative shadow-2xl min-h-[450px]">

      {/* 始終存在的 Video 標籤，透過 opacity 控制顯示 */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className={`h-full w-full object-cover transition-opacity duration-500 ${isReady ? 'opacity-100' : 'opacity-0'}`} 
      />

      {/* 載入與錯誤畫面 */}
      {!isReady && (
        <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center bg-[#0f172a] z-10">
          <div className="w-20 h-20 bg-indigo-500/10 rounded-full flex items-center justify-center mb-6 text-indigo-400">
             {isLoading ? (
                <i className="fa-solid fa-circle-notch fa-spin text-3xl"></i>
             ) : (
                <i className="fa-solid fa-camera text-3xl"></i>
             )}
          </div>

          {error ? (
            <div className="animate-in fade-in">
              <h3 className="text-white font-bold text-lg mb-4">無法開啟</h3>
              <p className="text-slate-400 text-xs mb-8 leading-relaxed px-4">{error}</p>
              <button onClick={startCamera} className="bg-indigo-600 text-white py-3 px-8 rounded-xl font-bold shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">
                再次重試
              </button>
            </div>
          ) : (
            <div className="animate-in fade-in">
              <h3 className="text-white font-bold text-xl mb-3">準備掃描</h3>
              <p className="text-slate-400 text-xs mb-10 px-6">
                {isLoading ? "相機啟動中，請稍候..." : "請點擊下方按鈕啟動掃描器"}
              </p>
              {!isLoading && (
                <button onClick={startCamera} className="bg-white text-slate-900 py-4 px-10 rounded-2xl font-black shadow-xl active:scale-95 transition-all">
                  點擊啟動攝影機
                </button>
              )}
            </div>
          )}
        </div>
      )}

      {/* 掃描 UI 層 (僅在就緒時顯示) */}
      {isReady && (
        <>
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/20 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(15,23,42,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-500 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-500 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-500 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-500 translate-x-1 translate-y-1 rounded-br-lg"></div>
                <div className="absolute top-0 left-0 w-full h-1 bg-indigo-400/50 animate-[scan_2s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center z-20">
            <button 
              onClick={capture} 
              className="w-20 h-20 rounded-full bg-white border-8 border-white/20 shadow-2xl active:scale-90 transition-transform flex items-center justify-center"
            >
              <div className="w-12 h-12 rounded-full bg-indigo-600"></div>
            </button>
          </div>

          <button 
            onClick={() => { stopTracks(); onClose(); }} 
            className="absolute top-6 left-6 w-10 h-10 bg-black/40 text-white rounded-xl flex items-center justify-center backdrop-blur-md z-20"
          >
            <i className="fa-solid fa-xmark"></i>
          </button>
        </>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan {
          0% { top: 0%; }
          100% { top: 100%; }
        }
      `}</style>
    </div>
  );
};

