import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 5);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isExporting, setIsExporting] = useState(false);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };

    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
  }, [selectedCardId]);

  const handlePlanChange = async (newPlan: ApiPlan) => {
    if (newPlan === 'paid') {
      // @ts-ignore
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      if (!hasKey) {
        if (window.confirm("使用 Pro 高階功能需要設置您自己的 Google API Key。是否現在開啟選擇視窗？")) {
           // @ts-ignore
           await window.aistudio?.openSelectKey();
           setPlan('paid');
        }
      } else {
        setPlan('paid');
      }
    } else {
      setPlan('free');
    }
  };

  const downloadFile = (blob: Blob, fileName: string) => {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  const handleExportAndShare = (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) {
      alert(`目前沒有 ${category} 的資料可供匯出`);
      return;
    }
    setIsExporting(true);

    try {
      const exportData = targetCards.map(c => {
        const baseData: any = {
          'Source': 'Business Card',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
        };

        if (category === 'employer') {
          return {
            ...baseData,
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Phone (Optional)': c.phone || c.mobile || '',
          };
        } else {
          return {
            ...baseData,
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Subject': c.subject || '',
            'Phone (Optional)': c.phone || c.mobile || '',
          };
        }
      });

      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, `QS_${category}`);

      const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
      const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const fileName = `QS_Hub_${category.toUpperCase()}_${new Date().toISOString().split('T')[0]}.xlsx`;
      const file = new File([blob], fileName, { type: blob.type });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({
          files: [file],
          title: `QS Hub ${category} 資料匯出`,
        }).catch(() => downloadFile(blob, fileName));
      } else {
        downloadFile(blob, fileName);
      }
    } catch (e) {
      console.error("Export Error:", e);
    } finally {
      setIsExporting(false);
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案讀取失敗");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      if (err.message === "API_KEY_NOT_FOUND") {
         alert("API Key 無效或未授權，請重新選擇有效的 Google API Key。");
         // @ts-ignore
         window.aistudio?.openSelectKey();
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      <aside 
        style={{ width: isMobile ? '100%' : `400px` }} 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-in-out bg-white flex flex-col border-r border-slate-200 shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 border-b bg-slate-50/50">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
               <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-200">
                 <i className="fa-solid fa-bahai text-lg"></i>
               </div>
               <div className="flex flex-col">
                 <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest leading-none mb-1">QS HUB Scanner</h2>
                 <span className="text-[9px] font-bold text-indigo-500 uppercase tracking-tighter">System Version 1.2</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-200/50 rounded-full text-slate-400"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="space-y-4 mb-8">
            <div className="flex bg-slate-200/50 p-1.5 rounded-2xl border border-slate-200">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${plan === 'free' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>免費辨識</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-500'}`}>自定義 API</button>
            </div>
            <p className="text-[10px] text-slate-400 text-center font-bold px-2">
              {plan === 'paid' ? '✓ PRO 模型啟動中' : '● 目前使用 FLASH 預覽模型'}
            </p>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => handleExportAndShare('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => handleExportAndShare('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => handleExportAndShare('staff')} />
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden bg-slate-50/20">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] relative">
        <header className="h-20 border-b border-slate-200/50 flex items-center justify-between px-6 shrink-0 bg-white/60 backdrop-blur-2xl sticky top-0 z-50">
           <div className="flex items-center gap-4 overflow-hidden w-full">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-12 h-12 flex items-center justify-center bg-indigo-50 rounded-2xl text-indigo-600 shrink-0 shadow-sm border border-indigo-100"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-200/40 p-1.5 rounded-2xl overflow-x-auto no-scrollbar max-w-full">
                <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => { setViewMode('camera'); setRotation(0); }} />
                <NavBtn icon="fa-folder-open" label="批次上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="辨識狀態" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
