import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("瀏覽器不支援相機功能，請更換至 Chrome 或 Safari。");
      return;
    }

    setIsLoading(true);
    setError(null);
    stopTracks();

    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: "environment",
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        }, 
        audio: false 
      });

      setStream(mediaStream);

      if (videoRef.current) {
        const video = videoRef.current;
        video.srcObject = mediaStream;

        video.onloadedmetadata = () => {
          video.play().then(() => {
            setIsReady(true);
            setIsLoading(false);
          }).catch(err => {
            console.error("Play failed:", err);
            setIsReady(true);
            setIsLoading(false);
          });
        };
      } else {
        throw new Error("找不到影像播放元件");
      }

    } catch (err: any) {
      console.error("Camera Error:", err);
      setIsLoading(false);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("權限不足：請允許相機存取。");
      } else {
        setError("相機啟動失敗，請確認沒有其他應用程式正在佔用。");
      }
    }
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-[#0f172a] rounded-[3.5rem] overflow-hidden relative shadow-2xl min-h-[500px] border border-white/5">

      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className={`h-full w-full object-cover transition-opacity duration-700 ${isReady ? 'opacity-100' : 'opacity-0'}`} 
      />

      {!isReady && (
        <div className="absolute inset-0 flex flex-col items-center justify-center p-12 text-center bg-[#0f172a] z-10">
          <div className="w-24 h-24 bg-indigo-500/20 rounded-[2.5rem] flex items-center justify-center mb-8 text-indigo-400 shadow-inner">
             {isLoading ? (
                <i className="fa-solid fa-circle-notch fa-spin text-4xl"></i>
             ) : (
                <i className="fa-solid fa-camera-retro text-4xl"></i>
             )}
          </div>

          {error ? (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-white font-black text-2xl mb-4 tracking-tight">無法開啟掃描器</h3>
              <p className="text-slate-400 text-sm mb-10 leading-relaxed max-w-xs">{error}</p>
              <button onClick={startCamera} className="bg-indigo-600 text-white py-4 px-12 rounded-[1.5rem] font-black shadow-2xl shadow-indigo-600/30 active:scale-95 transition-all text-lg uppercase tracking-widest">
                重新嘗試
              </button>
            </div>
          ) : (
            <div className="animate-in fade-in duration-500">
              <h3 className="text-white font-black text-3xl mb-4 tracking-tight">智能掃描模式</h3>
              <p className="text-slate-400 text-sm mb-12 px-6 max-w-sm leading-relaxed">
                {isLoading ? "正在建立連線並校正畫質..." : "系統已就緒。啟動攝影機後將名片對準框線，AI 將自動進行資料擷取。"}
              </p>
              {!isLoading && (
                <button onClick={startCamera} className="bg-white text-slate-900 py-5 px-14 rounded-[2rem] font-black shadow-2xl active:scale-95 transition-all text-xl uppercase tracking-[0.2em] flex items-center gap-4">
                  <i className="fa-solid fa-power-off text-indigo-500"></i>
                  啟動掃描
                </button>
              )}
            </div>
          )}
        </div>
      )}

      {isReady && (
        <>
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-md aspect-[1.6/1] border-2 border-white/30 rounded-[2rem] relative shadow-[0_0_0_100vmax_rgba(15,23,42,0.5)]">
                <div className="absolute top-0 left-0 w-10 h-10 border-t-8 border-l-8 border-indigo-500 -translate-x-2 -translate-y-2 rounded-tl-[1.5rem]"></div>
                <div className="absolute top-0 right-0 w-10 h-10 border-t-8 border-r-8 border-indigo-500 translate-x-2 -translate-y-2 rounded-tr-[1.5rem]"></div>
                <div className="absolute bottom-0 left-0 w-10 h-10 border-b-8 border-l-8 border-indigo-500 -translate-x-2 translate-y-2 rounded-bl-[1.5rem]"></div>
                <div className="absolute bottom-0 right-0 w-10 h-10 border-b-8 border-r-8 border-indigo-500 translate-x-2 translate-y-2 rounded-br-[1.5rem]"></div>

                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent animate-[scan_2.5s_infinite_linear] shadow-[0_0_20px_rgba(129,140,248,0.8)]"></div>

                <div className="absolute -top-12 left-1/2 -translate-x-1/2 text-white/40 text-[10px] font-black uppercase tracking-[0.4em] whitespace-nowrap">
                   Align Business Card Inside Frame
                </div>
             </div>
          </div>

          <div className="absolute bottom-16 left-0 right-0 flex justify-center z-20">
            <button 
              onClick={capture} 
              className="w-24 h-24 rounded-full bg-white/10 border-[8px] border-white/20 p-1.5 active:scale-90 transition-all shadow-2xl group"
            >
              <div className="w-full h-full rounded-full bg-white flex items-center justify-center shadow-[0_0_50px_rgba(255,255,255,0.3)]">
                <i className="fa-solid fa-camera text-indigo-600 text-3xl"></i>
              </div>
            </button>
          </div>

          <button 
            onClick={() => { stopTracks(); onClose(); }} 
            className="absolute top-8 left-8 w-14 h-14 bg-black/40 text-white rounded-[1.25rem] flex items-center justify-center backdrop-blur-2xl border border-white/10 active:scale-90 transition-all z-20"
          >
            <i className="fa-solid fa-xmark text-xl"></i>
          </button>
        </>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

