               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-11 h-11 flex items-center justify-center bg-slate-100 rounded-2xl text-slate-500"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="space-y-4 mb-6">
            <div className="flex bg-slate-100 p-1.5 rounded-2xl">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${plan === 'free' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500'}`}>Flash (Free)</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-500'}`}>Pro (Paid)</button>
            </div>
          </div>

          {/* Category Tabs */}
          <div className="grid grid-cols-3 gap-2">
            <Tab color="indigo" label="Employer" active={activeCategory === 'employer'} onClick={() => setActiveCategory('employer')} count={cards.filter(c=>c.category==='employer').length} />
            <Tab color="emerald" label="Academic" active={activeCategory === 'academic'} onClick={() => setActiveCategory('academic')} count={cards.filter(c=>c.category==='academic').length} />
            <Tab color="amber" label="Staff" active={activeCategory === 'staff'} onClick={() => setActiveCategory('staff')} count={cards.filter(c=>c.category==='staff').length} />
          </div>
        </div>

