import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
    if (videoRef.current) videoRef.current.srcObject = null;
  };

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    stopTracks();

    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } }, 
        audio: false 
      });

      setStream(mediaStream);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().then(() => {
            setIsReady(true);
            setIsLoading(false);
          });
        };
      }
    } catch (err: any) {
      setIsLoading(false);
      setError("無法開啟相機，請檢查權限設定。");
    }
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        onCapture(canvas.toDataURL('image/jpeg', 0.9).split(',')[1]);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2.5rem] lg:rounded-[3.5rem] overflow-hidden relative shadow-2xl min-h-[450px]">
      <video ref={videoRef} autoPlay playsInline muted className={`h-full w-full object-cover transition-opacity duration-700 ${isReady ? 'opacity-100' : 'opacity-0'}`} />

      {!isReady && (
        <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-slate-900 z-10">
          <div className="w-20 h-20 bg-indigo-500/20 rounded-3xl flex items-center justify-center mb-6 text-indigo-400">
             {isLoading ? <i className="fa-solid fa-circle-notch fa-spin text-3xl"></i> : <i className="fa-solid fa-camera text-3xl"></i>}
          </div>
          <h3 className="text-white font-black text-xl mb-3 tracking-tight">智能掃描開啟中</h3>
          <p className="text-slate-400 text-xs mb-8 leading-relaxed px-4">{error || (isLoading ? "正在調用硬體設備..." : "請將名片置於相機框線內進行自動辨識。")}</p>
          {!isLoading && <button onClick={startCamera} className="bg-indigo-600 text-white py-4 px-10 rounded-2xl font-black shadow-xl active:scale-95 transition-all uppercase tracking-widest text-sm">點擊啟動相機</button>}
        </div>
      )}

      {isReady && (
        <>
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-[85%] max-w-sm aspect-[1.6/1] border-2 border-white/20 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(15,23,42,0.6)]">
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500 translate-x-1 translate-y-1 rounded-br-lg"></div>
                <div className="absolute top-0 left-0 w-full h-1 bg-indigo-400/50 animate-[scan_2s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-10 flex justify-center w-full z-20">
            <button onClick={capture} className="w-20 h-20 rounded-full bg-white border-8 border-slate-100/30 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
              <div className="w-12 h-12 rounded-full bg-indigo-600"></div>
            </button>
          </div>

          <button onClick={() => { stopTracks(); onClose(); }} className="absolute top-6 right-6 w-11 h-11 bg-black/40 text-white rounded-xl flex items-center justify-center backdrop-blur-md z-20">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </>
      )}
      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan { 0% { top: 0%; } 100% { top: 100%; } }
      `}</style>
    </div>
  );
};

export default CameraScanner;

import React, { useState, useEffect, useRef, useMemo } from 'react';
