                  <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 relative group overflow-hidden">
                    <div className="absolute top-0 left-0 w-2 h-full bg-indigo-500 opacity-20 group-hover:opacity-100 transition-opacity"></div>
                    <span className="block font-black uppercase text-[10px] text-slate-400 mb-4 tracking-[0.3em]">AI 判斷邏輯報告</span>
