                <div className="absolute bottom-0 left-0 w-12 h-12 border-b-[6px] border-l-[6px] border-indigo-500 -translate-x-1 translate-y-1 rounded-bl-[1.8rem]"></div>
                <div className="absolute bottom-0 right-0 w-12 h-12 border-b-[6px] border-r-[6px] border-indigo-500 translate-x-1 translate-y-1 rounded-br-[1.8rem]"></div>

                {/* Scanning Animation */}
                <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-transparent via-indigo-400 to-transparent animate-[scan_3s_infinite_linear] opacity-70"></div>
                <div className="absolute inset-0 bg-indigo-500/5 animate-pulse"></div>

                <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-white/40 text-[9px] font-black uppercase tracking-[0.5em] whitespace-nowrap">
