          <button onClick={() => { stopTracks(); onClose(); }} className="absolute top-10 right-10 w-14 h-14 bg-white/10 text-white rounded-2xl flex items-center justify-center backdrop-blur-2xl border border-white/10 active:scale-90 transition-all z-20">
            <i className="fa-solid fa-xmark text-xl"></i>
