               <div className="w-full lg:w-[540px] p-8 lg:p-16 space-y-12 lg:overflow-y-auto custom-scrollbar">
                  <header>
                    <div className={`inline-block px-5 py-2 rounded-xl text-[11px] font-black uppercase tracking-[0.2em] mb-6 shadow-sm ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-700' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                      {selectedCard.category} Verified
                    </div>
                    <h1 className="text-4xl lg:text-5xl font-black text-slate-900 leading-[1.1] mb-4 tracking-tighter">
                      {[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}
                    </h1>
                    <p className="text-indigo-600 font-black text-xl lg:text-2xl tracking-tight">{selectedCard.title || 'Unknown Position'}</p>
                  </header>

                  <div className="grid gap-y-10">
                    <Field label="組織單位 / 公司名稱" value={selectedCard.company} icon="fa-building" />
                    <Field label="電子郵件信箱" value={selectedCard.email} icon="fa-envelope" />
                    <Field label="部門 / 學術領域" value={selectedCard.department || selectedCard.subject} icon="fa-sitemap" />
                    <div className="grid grid-cols-2 gap-10">
                      <Field label="國家地區" value={selectedCard.country} icon="fa-earth-asia" />
                      <Field label="聯繫電話" value={selectedCard.phone} icon="fa-phone" />
                    </div>
                  </div>

                  <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 relative group overflow-hidden">
