type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => { setRotation(0); }, [selectedCardId]);

  const handlePlanChange = async (newPlan: ApiPlan) => {
    if (newPlan === 'paid') {
      // @ts-ignore
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      if (!hasKey) {
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setPlan('paid');
    } else {
      setPlan('free');
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      if (err.message === "API_KEY_INVALID") {
        setPlan('free');
        alert("目前的 API Key 無效，請確認您選擇的是付費專案的 Key。系統已自動切換回免費模式。");
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) return alert(`目前沒有 ${category} 的資料`);

    const exportData = targetCards.map(c => ({
      'Title': c.prefix || '',
      'First Name': c.firstName || '',
      'Last Name': c.lastName || '',
      'Company/Institution': c.company || '',
      'Email': c.email || '',
      'Position': c.title || '',
      'Department': c.department || '',
      'Industry': c.industry || '',
      'Country': c.country || '',
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Cards");

    const fileName = `QS_Hub_${category}_${new Date().toISOString().split('T')[0]}.xlsx`;

    // 行動端分享邏輯
    const canShare = !!navigator.share && !!navigator.canShare;

    if (isMobile && canShare) {
      try {
        // 將 Excel 轉換為 Blob
        const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const file = new File([blob], fileName, { type: blob.type });

        if (navigator.canShare({ files: [file] })) {
          await navigator.share({
            files: [file],
            title: `QS Hub ${category} List`,
            text: '這是我從 QS Hub Scanner 匯出的名片清單。'
          });
          return; // 分享成功，結束
        }
      } catch (err) {
        console.warn("Share failed, falling back to download", err);
      }
    }

    // 桌機或不支援分享時使用下載
    XLSX.writeFile(wb, fileName);
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#f0f2f5] text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-900">
      {/* Sidebar Drawer */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-all duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[440px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-8 bg-white border-b border-slate-100">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white shadow-xl shadow-indigo-100 transform -rotate-3">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div className="leading-tight">
                 <h2 className="text-xl font-black text-slate-800 tracking-tight">QS HUB</h2>
                 <span className="text-[11px] font-black text-indigo-500 uppercase tracking-widest">Digital Scanner</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 active:scale-90 transition-transform"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="space-y-4 mb-8">
            <div className="bg-slate-50 p-1.5 rounded-[1.5rem] flex shadow-inner relative">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'free' ? 'bg-white text-indigo-600 shadow-md translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Flash (Free)</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Pro Mode</button>
            </div>
            <div className="flex items-center justify-center gap-2">
              <span className={`text-[10px] font-black uppercase tracking-widest ${plan === 'paid' ? 'text-indigo-600' : 'text-slate-400'}`}>
                {plan === 'paid' ? '✓ Pro Key Enabled' : '● Free Access Mode'}
              </span>
              <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="text-slate-300 hover:text-indigo-400 transition-colors">
                <i className="fa-solid fa-circle-info text-xs"></i>
              </a>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <Tab color="indigo" label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <Tab color="emerald" label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <Tab color="amber" label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50/50 space-y-4">
           <div className="flex items-center justify-between sticky top-0 z-10 py-1 bg-slate-50/50 backdrop-blur-sm">
              <h3 className="text-xs font-black uppercase text-slate-400 tracking-[0.25em]">{activeCategory}s ({cards.filter(c => c.category === activeCategory).length})</h3>
              <button 
                onClick={() => handleExport(activeCategory)} 
                className="text-[11px] font-black text-white px-4 py-2 bg-slate-900 rounded-xl hover:bg-slate-800 active:scale-95 transition-all shadow-lg shadow-slate-200 flex items-center gap-2"
              >
                <i className={`fa-solid ${isMobile ? 'fa-share-nodes' : 'fa-download'}`}></i>
                {isMobile ? '分享' : 'EXCEL'}
              </button>
           </div>

           <div className="space-y-3">
             {cards.filter(c => c.category === activeCategory).map(c => (
                <div 
                  key={c.id} 
                  onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                  className={`group p-5 rounded-[1.75rem] cursor-pointer border-2 transition-all duration-300 ${selectedCardId === c.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl shadow-indigo-200 -translate-y-1' : 'bg-white border-transparent hover:border-indigo-100 hover:shadow-xl shadow-sm'}`}
                >
                  <div className="font-bold text-base mb-1 tracking-tight">{c.firstName} {c.lastName}</div>
                  <div className={`text-xs font-medium truncate opacity-70 ${selectedCardId === c.id ? 'text-indigo-50' : 'text-slate-500'}`}>{c.company}</div>
                </div>
             ))}
             {cards.filter(c => c.category === activeCategory).length === 0 && (
               <div className="py-24 text-center">
                 <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner text-slate-200">
                   <i className="fa-solid fa-folder-open text-3xl"></i>
                 </div>
                 <p className="text-xs font-black uppercase tracking-widest text-slate-300 italic">No records found</p>
               </div>
             )}
           </div>
        </div>
      </aside>

      {/* Main Viewport */}
      <main className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] relative">
        <header className="h-18 lg:h-22 px-4 lg:px-8 border-b border-slate-200/50 flex items-center justify-between bg-white/80 backdrop-blur-2xl sticky top-0 z-50">
           <div className="flex items-center gap-4 w-full overflow-hidden">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-12 h-12 flex items-center justify-center bg-indigo-50 rounded-2xl text-indigo-600 shrink-0 shadow-sm"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1.5 rounded-[1.25rem] overflow-x-auto no-scrollbar max-w-full">
                <NavBtn icon="fa-camera-retro" label="掃描名片" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-file-arrow-up" label="檔案上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-bolt-lightning" label="辨識狀態" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-circle-check" label="核對資訊" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-5 lg:p-10">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto flex flex-col">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `掃描_${new Date().toLocaleTimeString()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center">
