                className="w-full max-w-xl p-12 lg:p-20 border-3 border-dashed border-slate-200 rounded-[3rem] bg-white shadow-2xl hover:border-indigo-400 hover:bg-indigo-50/10 transition-all duration-500 cursor-pointer text-center group" 
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-24 h-24 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 group-hover:scale-110 group-hover:rotate-6 transition-all shadow-inner">
                  <i className="fa-solid fa-images text-3xl text-indigo-600"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-4">匯入名片圖檔</h3>
                <p className="text-slate-400 text-sm font-bold tracking-widest leading-relaxed uppercase max-w-xs mx-auto">
                  選擇多張名片進行<br/>批次辨識<br/>
                  <span className="text-indigo-600 mt-4 block text-[10px] bg-indigo-50 py-1 rounded-full px-4">{plan.toUpperCase()} AI PROCESSING</span>
