                    <div className={`inline-block px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] mb-4 shadow-sm ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-700' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                      {selectedCard.category} Mode
                    </div>
                    <h1 className="text-3xl lg:text-5xl font-black text-slate-900 leading-[1.1] mb-2 tracking-tighter">
                      {[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}
                    </h1>
                    <p className="text-indigo-600 font-black text-lg lg:text-2xl tracking-tight">{selectedCard.title || 'Unknown Position'}</p>
                  </header>

                  <div className="grid gap-y-8 lg:gap-y-10">
                    <Field label="組織單位 / 公司名稱" value={selectedCard.company} icon="fa-building" />
                    <Field label="電子郵件信箱" value={selectedCard.email} icon="fa-envelope" />
                    <Field label="部門 / 學術領域" value={selectedCard.department || selectedCard.subject} icon="fa-sitemap" />
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-10">
                      <Field label="國家地區" value={selectedCard.country} icon="fa-earth-asia" />
                      <Field label="聯繫電話" value={selectedCard.phone} icon="fa-phone" />
                    </div>
                  </div>

                  <div className="p-6 lg:p-8 bg-slate-50 rounded-[2rem] border border-slate-100 relative group overflow-hidden">
                    <div className="absolute top-0 left-0 w-1.5 h-full bg-indigo-500 opacity-20 group-hover:opacity-100 transition-opacity"></div>
                    <span className="block font-black uppercase text-[9px] text-slate-400 mb-2 tracking-[0.3em]">AI 判定報告</span>
                    <p className="text-xs lg:text-sm text-slate-600 leading-relaxed font-semibold">{selectedCard.reasoning}</p>
                  </div>
               </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-30 grayscale p-12 text-center">
               <div className="w-32 h-32 bg-white rounded-full flex items-center justify-center mb-8 shadow-inner">
                  <i className="fa-solid fa-address-card text-5xl text-slate-200"></i>
               </div>
               <p className="text-xs font-black uppercase tracking-[0.5em] text-slate-400">Please select a record</p>
            </div>
          )}
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[90] animate-in fade-in duration-500" onClick={() => setIsSidebarOpen(false)} />}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #cbd5e1; }
