type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => { setRotation(0); }, [selectedCardId]);

  const handlePlanChange = async (newPlan: ApiPlan) => {
    if (newPlan === 'paid') {
      // @ts-ignore
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      if (!hasKey) {
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setPlan('paid');
    } else {
      setPlan('free');
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      if (err.message === "API_KEY_INVALID") {
        setPlan('free');
        alert("目前的 API Key 無效，請確認您選擇的是付費專案的 Key。系統已自動切換回免費模式。");
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) return alert(`目前沒有 ${category} 的資料`);

    setIsExporting(true);
    try {
      const exportData = targetCards.map(c => ({
        'Title': c.prefix || '',
        'First Name': c.firstName || '',
        'Last Name': c.lastName || '',
        'Company/Institution': c.company || '',
        'Email': c.email || '',
        'Position': c.title || '',
        'Department': c.department || '',
        'Industry': c.industry || '',
        'Country': c.country || '',
      }));

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");

      const fileName = `QS_Hub_${category}_${new Date().toISOString().split('T')[0]}.xlsx`;

      // 優化行動端分享邏輯
      if (isMobile && navigator.share) {
        try {
          const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
          const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
          const file = new File([blob], fileName, { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

          // 檢查是否可分享，即使失敗也嘗試直接分享 (某些瀏覽器 canShare 回傳不準確)
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
             await navigator.share({
               files: [file],
               title: 'QS HUB 匯出',
               text: '請選擇 LINE 或其他 App 分享 Excel 檔案。'
             });
             return;
          } else {
             // 嘗試直接分享
             await navigator.share({
               files: [file]
             });
             return;
          }
        } catch (shareErr) {
          console.warn("Navigator.share failed:", shareErr);
        }
      }

      // 降級方案：下載
      XLSX.writeFile(wb, fileName);
    } catch (err) {
      console.error("Export error:", err);
      alert("匯出處理發生錯誤。");
    } finally {
      setIsExporting(false);
    }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#f0f2f5] text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-900">
      {/* Sidebar Drawer */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-all duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[440px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-8 bg-white border-b border-slate-100">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white shadow-xl shadow-indigo-100 transform -rotate-3">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div className="leading-tight">
                 <h2 className="text-xl font-black text-slate-800 tracking-tight">QS HUB</h2>
                 <span className="text-[11px] font-black text-indigo-500 uppercase tracking-widest">Digital Scanner</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 active:scale-90 transition-transform"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="space-y-4 mb-8">
            <div className="bg-slate-50 p-1.5 rounded-[1.5rem] flex shadow-inner relative">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'free' ? 'bg-white text-indigo-600 shadow-md translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Flash (Free)</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Pro Mode</button>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <Tab color="indigo" label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <Tab color="emerald" label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <Tab color="amber" label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50/50 space-y-4">
           <div className="flex items-center justify-between sticky top-0 z-10 py-1 bg-slate-50/50 backdrop-blur-sm">
              <h3 className="text-xs font-black uppercase text-slate-400 tracking-[0.25em]">{activeCategory}s ({cards.filter(c => c.category === activeCategory).length})</h3>
              <button 
                onClick={() => handleExport(activeCategory)} 
                disabled={isExporting}
                className={`text-[11px] font-black text-white px-5 py-2.5 bg-slate-900 rounded-xl hover:bg-slate-800 active:scale-95 transition-all shadow-lg shadow-slate-200 flex items-center gap-2 ${isExporting ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <i className={`fa-solid ${isExporting ? 'fa-circle-notch fa-spin' : isMobile ? 'fa-share-nodes' : 'fa-download'}`}></i>
                {isExporting ? '處理中' : isMobile ? '分享清單' : '匯出 EXCEL'}
              </button>
           </div>

           <div className="space-y-3">
             {cards.filter(c => c.category === activeCategory).map(c => (
                <div 
                  key={c.id} 
                  onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                  className={`group p-5 rounded-[1.75rem] cursor-pointer border-2 transition-all duration-300 ${selectedCardId === c.id ? 'bg-indigo-600 border-indigo-600 text-white shadow-2xl shadow-indigo-200 -translate-y-1' : 'bg-white border-transparent hover:border-indigo-100 hover:shadow-xl shadow-sm'}`}
                >
                  <div className="font-bold text-base mb-1 tracking-tight">{c.firstName} {c.lastName}</div>
                  <div className={`text-xs font-medium truncate opacity-70 ${selectedCardId === c.id ? 'text-indigo-50' : 'text-slate-500'}`}>{c.company}</div>
                </div>
             ))}
           </div>
        </div>
      </aside>

      {/* Main Viewport */}
      <main className="flex-1 flex flex-col min-w-0 bg-[#f8fafc] relative">
        <header className="h-16 lg:h-22 px-4 lg:px-8 border-b border-slate-200/50 flex items-center justify-between bg-white/80 backdrop-blur-2xl sticky top-0 z-[60]">
           <div className="flex items-center gap-4 w-full overflow-hidden">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-indigo-50 rounded-xl text-indigo-600 shrink-0 shadow-sm"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1 rounded-[1.25rem] overflow-x-auto no-scrollbar max-w-full">
                <NavBtn icon="fa-camera-retro" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-file-arrow-up" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-bolt-lightning" label="進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-circle-check" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className={`flex-1 overflow-y-auto custom-scrollbar ${viewMode === 'detail' && isMobile ? 'bg-slate-900 overflow-x-hidden' : 'bg-slate-50'}`}>
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto flex flex-col p-5 lg:p-10">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `掃描_${new Date().toLocaleTimeString()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center p-5 lg:p-10">
              <div 
                className="w-full max-w-xl p-12 lg:p-20 border-3 border-dashed border-slate-200 rounded-[3rem] bg-white shadow-2xl hover:border-indigo-400 hover:bg-indigo-50/10 transition-all duration-500 cursor-pointer text-center group" 
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-8 group-hover:scale-110 transition-all shadow-inner">
                  <i className="fa-solid fa-images text-2xl text-indigo-600"></i>
                </div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight mb-3">匯入名片圖檔</h3>
                <p className="text-slate-400 text-xs font-bold tracking-widest leading-relaxed uppercase max-w-xs mx-auto mb-6">點擊此處選擇照片</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID();
                    filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1, plan };
                  });
                  setTasks(prev => [...prev, ...newTasks]);
                  setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-3xl mx-auto space-y-6 animate-in fade-in duration-700 p-5 lg:p-10">
              <h2 className="font-black text-2xl text-slate-800 border-b border-slate-100 pb-4">處理隊列 ({tasks.length})</h2>
              <div className="grid gap-4">
                {tasks.map(t => (
                  <div key={t.id} className="p-5 bg-white border border-slate-100 rounded-[1.75rem] flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        <i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : 'fa-spinner fa-spin'}`}></i>
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-slate-800 text-sm">{t.fileName}</span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{t.status}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : selectedCard ? (
            <div className="h-full flex flex-col lg:flex-row lg:m-10 bg-white lg:rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 animate-in zoom-in-95 duration-500 relative">

               {/* Image Viewer Layer */}
               <div className={`lg:flex-1 bg-slate-900 flex flex-col items-center justify-center border-b lg:border-r border-slate-800 relative ${isMobile ? 'sticky top-0 z-[55] h-[40vh] shadow-2xl' : 'p-14'}`}>
                  {isMobile && (
                     <div className="absolute top-4 right-4 z-[56] flex gap-2">
                         <button onClick={() => setRotation(r => r + 90)} className="w-10 h-10 bg-black/50 backdrop-blur-xl rounded-full flex items-center justify-center text-white active:scale-90 border border-white/10 shadow-lg"><i className="fa-solid fa-rotate-right"></i></button>
                     </div>
                  )}
                  {!isMobile && (
                    <div className="absolute top-10 left-10 flex flex-col">
                       <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400 mb-1">Visual Reference</span>
                       <h4 className="text-white font-black text-lg">原始影像對照</h4>
                    </div>
                  )}
                  <div className={`w-full h-full flex items-center justify-center ${isMobile ? 'p-4' : 'p-8'}`}>
                    <img 
                      src={selectedCard.imageUrl} 
                      className="max-w-full max-h-full transition-transform duration-700 rounded shadow-[0_20px_60px_rgba(0,0,0,0.5)] border border-white/5" 
                      style={{ transform: `rotate(${rotation}deg)` }} 
                    />
                  </div>
                  {isMobile && (
                    <div className="absolute bottom-2 left-0 w-full text-center pointer-events-none">
                       <span className="text-[9px] font-black text-white/30 uppercase tracking-[0.4em] bg-black/40 px-3 py-1 rounded-full backdrop-blur-sm">Slide down to verify info</span>
                    </div>
                  )}
               </div>

               {/* Form Editor Layer */}
               <div className={`w-full lg:w-[500px] bg-white p-6 lg:p-12 space-y-8 lg:overflow-y-auto custom-scrollbar ${isMobile ? 'rounded-t-[2.5rem] -mt-6 relative z-[58] shadow-[0_-30px_50px_rgba(0,0,0,0.2)] pb-20' : ''}`}>
                  <header className="mb-8">
                    <div className={`inline-block px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest mb-3 ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-700' : 'bg-emerald-100 text-emerald-700'}`}>
                      {selectedCard.category} Verified
                    </div>
                    <h1 className="text-3xl lg:text-4xl font-black text-slate-900 tracking-tighter leading-tight">
                      {[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}
                    </h1>
                    <p className="text-indigo-600 font-bold text-lg">{selectedCard.title || 'Unknown Position'}</p>
                  </header>

                  <div className="grid gap-y-6">
                    <VerificationField label="公司名稱 / Institution" value={selectedCard.company} icon="fa-building" />
                    <VerificationField label="電子郵件" value={selectedCard.email} icon="fa-envelope" />
                    <VerificationField label="部門 / 學術領域" value={selectedCard.department || selectedCard.subject} icon="fa-sitemap" />
                    <div className="grid grid-cols-2 gap-4">
                      <VerificationField label="地區" value={selectedCard.country} icon="fa-earth-asia" />
                      <VerificationField label="電話" value={selectedCard.phone} icon="fa-phone" />
                    </div>
                  </div>

                  <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 relative group">
                    <span className="block font-black uppercase text-[9px] text-slate-400 mb-2 tracking-widest">AI 邏輯診斷</span>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">{selectedCard.reasoning}</p>
                  </div>
               </div>
            </div>
          ) : null}
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[90] animate-in fade-in duration-500" onClick={() => setIsSidebarOpen(false)} />}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

const VerificationField = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-1.5 group">
      <div className="flex items-center justify-between px-1">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-300`}></i>
          {label}
        </label>
        {value && (
          <button onClick={copy} className="text-[9px] font-black text-indigo-500 uppercase tracking-widest active:scale-90 transition-all">
            {copied ? '已複製' : '複製'}
          </button>
        )}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-3 lg:p-4 rounded-2xl font-black text-slate-800 text-sm lg:text-lg tracking-tight group-focus-within:border-indigo-200 transition-all">
        {value || '---'}
      </div>
    </div>
  );
};

const Tab = ({ color, label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center p-3 rounded-2xl transition-all duration-300 border-2 active:scale-95 ${active ? `bg-${color}-50 border-${color}-600 text-${color}-700 shadow-lg shadow-${color}-100` : 'bg-white border-transparent text-slate-300 hover:bg-slate-50'}`}>
    <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-60">{label}</span>
    <span className="text-base font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-4 rounded-xl transition-all duration-300 font-black text-[10px] uppercase tracking-widest whitespace-nowrap active:scale-95 ${active ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden xs:inline">{label}</span>
  </button>
);

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => { setRotation(0); }, [selectedCardId]);

  const handlePlanChange = async (newPlan: ApiPlan) => {
    if (newPlan === 'paid') {
      // @ts-ignore
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      if (!hasKey) {
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setPlan('paid');
    } else {
      setPlan('free');
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      if (err.message === "API_KEY_INVALID") {
        setPlan('free');
        alert("目前的 API Key 無效，請確認您選擇的是付費專案的 Key。系統已自動切換回免費模式。");
        // @ts-ignore
        await window.aistudio?.openSelectKey();
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) return alert(`目前沒有 ${category} 的資料`);

    setIsExporting(true);
    try {
      const exportData = targetCards.map(c => ({
        'Title': c.prefix || '',
        'First Name': c.firstName || '',
        'Last Name': c.lastName || '',
        'Company/Institution': c.company || '',
        'Email': c.email || '',
        'Position': c.title || '',
        'Department': c.department || '',
        'Industry': c.industry || '',
        'Country': c.country || '',
      }));

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");

      const fileName = `QS_Cards_${category}.xlsx`;
      const mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

      // 1. 產生 Excel 的 Uint8Array
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });

      // 2. 判斷是否為支援 Web Share 的行動端
      if (isMobile && navigator.share) {
        try {
          // 封裝成 Blob 再轉成 File 物件
          const blob = new Blob([wbout], { type: mimeType });
          const file = new File([blob], fileName, { type: mimeType });

          // 核心檢查：瀏覽器是否能分享此檔案
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
             await navigator.share({
               files: [file],
               title: 'QS Hub 資料匯出',
               text: `已自動生成 ${category} 名片清單。`
             });
             return;
          } else {
             // 如果 canShare 回報不支援，嘗試強制呼叫 (某些版本的 Chrome 仍可成功)
             await navigator.share({
               files: [file],
               title: 'QS Hub 匯出'
             });
             return;
          }
        } catch (shareErr: any) {
          // 如果使用者取消分享，不報錯；如果是系統錯誤則進入下載降級
          if (shareErr.name !== 'AbortError') {
             console.warn("Share logic encountered an issue:", shareErr);
          } else {
             return; // 使用者主動取消
          }
        }
      }

      // 3. 下載降級方案 (桌機或不支援分享的手機)
      const blob = new Blob([wbout], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

    } catch (err) {
      console.error("Critical Export error:", err);
      alert("匯出處理發生錯誤，請確認瀏覽器權限。");
    } finally {
      setIsExporting(false);
    }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#f0f2f5] text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-900">
      {/* Sidebar Drawer */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-all duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[440px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-8 bg-white border-b border-slate-100">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white shadow-xl shadow-indigo-100 transform -rotate-3">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div className="leading-tight">
                 <h2 className="text-xl font-black text-slate-800 tracking-tight">QS HUB</h2>
                 <span className="text-[11px] font-black text-indigo-500 uppercase tracking-widest">Digital Scanner</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 active:scale-90 transition-transform"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="space-y-4 mb-8">
            <div className="bg-slate-50 p-1.5 rounded-[1.5rem] flex shadow-inner relative">
               <button onClick={() => handlePlanChange('free')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'free' ? 'bg-white text-indigo-600 shadow-md translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Flash (Free)</button>
               <button onClick={() => handlePlanChange('paid')} className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-[1.1rem] transition-all duration-300 ${plan === 'paid' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 translate-y-[-1px]' : 'text-slate-400 hover:text-slate-600'}`}>Pro Mode</button>
