               {/* 頂部影像對照區 - 行動端為 Sticky */}
               <div className={`lg:flex-1 bg-slate-900 flex flex-col items-center justify-center relative ${isMobile ? 'sticky top-0 z-[55] h-[38vh] shadow-2xl border-b border-indigo-500/30' : 'p-14 border-r border-slate-100'}`}>
                  {isMobile && (
