                         <button onClick={() => setViewMode('file')} className="w-10 h-10 bg-black/50 backdrop-blur-xl rounded-full flex items-center justify-center text-white border border-white/10 shadow-lg"><i className="fa-solid fa-chevron-left"></i></button>
                     </div>
