                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `SCAN_${new Date().toLocaleTimeString()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
