                      <button onClick={() => setRotation(r => r + 90)} className="w-10 h-10 bg-black/40 backdrop-blur-xl rounded-full flex items-center justify-center text-white border border-white/10 shadow-lg active:scale-90"><i className="fa-solid fa-rotate-right"></i></button>
                  </div>

                  <div className={`w-full h-full flex items-center justify-center ${isMobile ? 'p-4' : 'p-6'}`}>
