                  <header className="border-b border-slate-50 pb-6">
                    <div className="flex items-center justify-between mb-3">
                      <div className={`inline-block px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-700' : 'bg-emerald-100 text-emerald-700'}`}>
                        {selectedCard.category} Verified
                      </div>
                      <button 
                        onClick={() => handleShareCard(selectedCard)}
                        className="text-xs font-black text-indigo-600 flex items-center gap-2 px-4 py-2 bg-indigo-50 rounded-xl active:scale-95 transition-all"
                      >
                        <i className="fa-solid fa-share-nodes"></i>
                        分享名片文字
                      </button>
                    </div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tighter leading-tight mb-1">
                      {[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}
                    </h1>
                    <p className="text-indigo-600 font-bold text-lg">{selectedCard.title || 'Unknown Position'}</p>
                  </header>

                  <div className="grid gap-y-6">
                    <VerifyRow label="公司 / 單位名稱" value={selectedCard.company} icon="fa-building" />
                    <VerifyRow label="電子郵件" value={selectedCard.email} icon="fa-envelope" />
                    <VerifyRow label="部門 / 學術領域" value={selectedCard.department || selectedCard.subject} icon="fa-sitemap" />
                    <div className="grid grid-cols-2 gap-4">
                      <VerifyRow label="國家/地區" value={selectedCard.country} icon="fa-earth-asia" />
                      <VerifyRow label="聯繫電話" value={selectedCard.phone} icon="fa-phone" />
                    </div>
                  </div>

                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                    <span className="block font-black uppercase text-[9px] text-slate-400 mb-2 tracking-widest">AI 智慧分析</span>
                    <p className="text-xs text-slate-500 leading-relaxed italic">{selectedCard.reasoning}</p>
                  </div>

                  {isMobile && (
                    <div className="fixed bottom-8 left-6 right-6 z-[70] flex gap-3">
                      <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl active:scale-95 transition-all">
                        確認並返回
                      </button>
                      <button onClick={() => handleShareCard(selectedCard)} className="w-16 h-16 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-2xl active:scale-90 transition-all">
                        <i className="fa-solid fa-share-nodes text-xl"></i>
                      </button>
                    </div>
                  )}
               </div>
            </div>
          ) : null}
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[90] animate-in fade-in duration-300" onClick={() => setIsSidebarOpen(false)} />}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>
    </div>
  );
};

const VerifyRow = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(15);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-2 group">
      <div className="flex items-center justify-between px-1">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-300`}></i>
          {label}
        </label>
        {value && (
          <button onClick={copy} className={`text-[9px] font-black uppercase tracking-widest active:scale-90 transition-all ${copied ? 'text-emerald-500' : 'text-indigo-400'}`}>
            {copied ? 'Copied!' : 'Copy'}
          </button>
        )}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-4 rounded-2xl font-black text-slate-800 text-sm tracking-tight shadow-sm active:bg-white transition-colors">
        {value || '---'}
      </div>
    </div>
  );
};

const Tab = ({ color, label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center p-3 rounded-2xl transition-all duration-300 border-2 active:scale-95 ${active ? `bg-${color}-50 border-${color}-600 text-${color}-700 shadow-lg shadow-${color}-100` : 'bg-white border-transparent text-slate-300 hover:bg-slate-50'}`}>
    <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-60">{label}</span>
    <span className="text-base font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-5 rounded-xl transition-all duration-300 font-black text-[10px] uppercase tracking-widest whitespace-nowrap active:scale-95 ${active ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden xs:inline">{label}</span>
  </button>
);

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  // 【核心改良】分享 Excel 檔案
  const handleExport = async (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const exportData = targetCards.map(c => ({
        'Full Name': `${c.prefix || ''} ${c.firstName} ${c.lastName}`.trim(),
        'Company': c.company || '',
        'Position': c.title || '',
        'Email': c.email || '',
        'Phone': c.phone || '',
        'Country': c.country || '',
      }));

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");

      const fileName = `QS-Data-${category}.xlsx`;
      const mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      const blob = new Blob([wbout], { type: mimeType });

      // 針對 Android Chrome 優化的分享邏輯
      if (navigator.share && isMobile) {
        try {
          const file = new File([blob], fileName, { type: mimeType });
          // 只分享檔案以避免環境限制導致的失敗
          const shareData = { files: [file] };

          if (navigator.canShare && navigator.canShare(shareData)) {
            await navigator.share(shareData);
            setIsExporting(false);
            return;
          }
        } catch (e) {
          console.warn("Share API restricted by sandbox/environment:", e);
        }
      }

      // 降級方案：直接觸發下載
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

    } catch (err) {
      console.error(err);
    } finally {
      setIsExporting(false);
    }
  };

  const handleShareCardText = async (card: BusinessCardData) => {
    const text = `【QS HUB 名片分享】\n姓名：${card.firstName} ${card.lastName}\n公司：${card.company}\n職稱：${card.title}\n電郵：${card.email}`;
    if (navigator.share) {
      try {
        await navigator.share({ text });
      } catch (e) {
        navigator.clipboard.writeText(text);
        alert("已複製到剪貼簿");
      }
    } else {
      navigator.clipboard.writeText(text);
      alert("已複製到剪貼簿");
    }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50 text-slate-900 font-sans">
      {/* Sidebar / List Drawer */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[420px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-10 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div className="leading-tight">
                 <h2 className="text-xl font-black text-slate-800 tracking-tight">QS HUB</h2>
                 <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest opacity-80">Digital Scanner</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-12 h-12 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 active:scale-90"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-2">
