const Field = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(10);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between px-1">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-300`}></i> {label}
        </label>
        {value && <button onClick={copy} className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">{copied ? 'Copied' : 'Copy'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-5 rounded-2xl font-black text-slate-800 text-sm tracking-tight shadow-sm">
        {value || '---'}
      </div>
    </div>
  );
};

const Tab = ({ color, label, active, count, onClick }: any) => (
