                    <div className="font-black text-xl mb-1 tracking-tight">{c.firstName} {c.lastName}</div>
                    <div className="text-[11px] font-bold opacity-80 truncate uppercase tracking-widest">{c.company}</div>
                  </div>
                </div>
             ))}
