                <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-upload" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className={`flex-1 overflow-y-auto custom-scrollbar ${viewMode === 'detail' && isMobile ? 'bg-[#050810]' : 'bg-white'}`}>
          {viewMode === 'camera' ? (
            <div className="h-full p-4 lg:p-10">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center p-8">
              <div 
                className="w-full max-w-lg p-12 border-3 border-dashed border-slate-100 rounded-[3rem] bg-slate-50/50 hover:bg-indigo-50 hover:border-indigo-200 transition-all duration-500 cursor-pointer text-center group" 
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-xl group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-image-portrait text-3xl text-indigo-600"></i>
                </div>
                <h3 className="text-xl font-black text-slate-800 mb-2">批次上傳名片照片</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">點擊選取多張圖檔</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID();
                    filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1, plan };
                  });
                  setTasks(prev => [...prev, ...newTasks]);
                  setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-2xl mx-auto p-6 lg:p-12 space-y-6">
              <h2 className="font-black text-2xl text-slate-800 mb-8">任務隊列 ({tasks.length})</h2>
              {tasks.map(t => (
                <div key={t.id} className="p-6 bg-white border border-slate-100 rounded-3xl flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                      <i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : 'fa-circle-notch fa-spin'}`}></i>
                    </div>
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800 text-sm truncate max-w-[150px]">{t.fileName}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{t.status}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : selectedCard ? (
            <div className="h-full flex flex-col lg:flex-row lg:m-10 bg-white lg:rounded-[3rem] shadow-2xl overflow-hidden relative border border-slate-50">

               {/* Image Viewer Area */}
               <div className={`lg:flex-1 bg-[#050810] flex items-center justify-center relative ${isMobile ? 'sticky top-0 z-[55] h-[40vh]' : 'p-12 border-r border-slate-50'}`}>
                  {isMobile && (
                    <button onClick={() => setViewMode('file')} className="absolute top-6 left-6 z-[60] w-12 h-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center text-white border border-white/10"><i className="fa-solid fa-chevron-left"></i></button>
                  )}
                  <div className="absolute top-6 right-6 z-[60] flex gap-2">
                    <button onClick={() => setRotation(r => r + 90)} className="w-12 h-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center text-white border border-white/10"><i className="fa-solid fa-rotate-right"></i></button>
                    <button onClick={() => setIsImageZoomed(true)} className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg"><i className="fa-solid fa-maximize"></i></button>
                  </div>

                  <div className="w-full h-full flex items-center justify-center p-4 cursor-zoom-in" onClick={() => setIsImageZoomed(true)}>
                    <img 
                      src={selectedCard.imageUrl} 
                      className="max-w-full max-h-full rounded shadow-2xl transition-transform duration-500" 
                      style={{ transform: `rotate(${rotation}deg)` }} 
                    />
                  </div>

                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 text-white/30 text-[9px] font-black uppercase tracking-[0.3em]">
                    Click Image to Zoom
                  </div>
               </div>

               {/* Data Forms */}
               <div className={`w-full lg:w-[520px] bg-white p-8 lg:p-12 space-y-10 lg:overflow-y-auto custom-scrollbar ${isMobile ? 'rounded-t-[3rem] -mt-10 relative z-[58] shadow-[0_-30px_80px_rgba(0,0,0,0.5)] pb-36' : ''}`}>
                  <header className="border-b border-slate-50 pb-8">
                    <div className="flex items-center justify-between mb-4">
                      <span className="px-3 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-black uppercase tracking-widest rounded-lg">AI Verified Data</span>
                    </div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">{selectedCard.firstName} {selectedCard.lastName}</h1>
                    <p className="text-indigo-600 font-black text-lg">{selectedCard.title || 'Unknown Position'}</p>
                  </header>

                  <div className="space-y-8">
                    <Field label="公司名稱" value={selectedCard.company} icon="fa-building" />
                    <Field label="電子郵件" value={selectedCard.email} icon="fa-envelope" />
                    <Field label="聯絡電話" value={selectedCard.phone} icon="fa-phone" />
                    <Field label="部門 / 領域" value={selectedCard.department || selectedCard.subject} icon="fa-sitemap" />
                    <Field label="國家/地區" value={selectedCard.country} icon="fa-earth-asia" />
                  </div>

                  <div className="p-6 bg-slate-50 rounded-[2.5rem] border border-slate-100">
                    <span className="block font-black text-[9px] text-slate-400 uppercase tracking-[0.2em] mb-3">AI 智慧分析結果</span>
                    <p className="text-xs text-slate-500 italic leading-relaxed">{selectedCard.reasoning}</p>
                  </div>

                  {isMobile && (
                    <div className="fixed bottom-8 left-8 right-8 z-[70]">
                      <button onClick={() => setViewMode('file')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl active:scale-95 transition-all">
                        確認並儲存
                      </button>
                    </div>
                  )}
               </div>

               {/* Fullscreen Image Zoom Overlay */}
               {isImageZoomed && (
                 <div className="fixed inset-0 z-[200] bg-black/95 flex items-center justify-center p-4 animate-in fade-in duration-300">
                    <button onClick={() => setIsImageZoomed(false)} className="absolute top-10 right-10 w-16 h-16 bg-white/10 text-white rounded-full flex items-center justify-center backdrop-blur-xl border border-white/20 active:scale-90 transition-all z-[210]">
                       <i className="fa-solid fa-xmark text-2xl"></i>
                    </button>
                    <div className="w-full h-full flex items-center justify-center overflow-auto custom-scrollbar">
                       <img 
                         src={selectedCard.imageUrl} 
                         className="max-w-none w-full lg:w-auto lg:h-[90vh] object-contain transition-transform duration-500 shadow-2xl" 
                         style={{ transform: `rotate(${rotation}deg)` }} 
                       />
                    </div>
                    <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-4">
                       <button onClick={() => setRotation(r => r + 90)} className="px-6 py-3 bg-white/10 text-white rounded-xl backdrop-blur-xl border border-white/10 font-black text-[10px] uppercase tracking-widest"><i className="fa-solid fa-rotate-right mr-2"></i> 旋轉圖片</button>
                       <button onClick={() => setIsImageZoomed(false)} className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest">關閉全螢幕</button>
                    </div>
                 </div>
               )}
            </div>
          ) : null}
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[90]" onClick={() => setIsSidebarOpen(false)} />}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

const Field = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(12);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between px-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-400`}></i> {label}
        </label>
        {value && <button onClick={copy} className="text-[10px] font-black text-indigo-500 uppercase tracking-widest active:scale-90 transition-all">{copied ? 'Copied' : 'Copy'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-6 rounded-[1.8rem] font-black text-slate-800 text-base tracking-tight shadow-sm active:bg-white transition-colors">
        {value || '---'}
      </div>
    </div>
  );
};

const Tab = ({ color, label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${active ? `bg-${color}-50 border-indigo-600 text-indigo-700 shadow-lg shadow-indigo-100` : 'bg-white border-transparent text-slate-300'}`}>
    <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-60">{label}</span>
    <span className="text-base font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2.5 px-6 rounded-xl transition-all font-black text-[11px] uppercase tracking-widest whitespace-nowrap active:scale-95 ${active ? 'bg-white shadow-lg text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden sm:inline">{label}</span>
  </button>
);

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff') => {
    const targetCards = cards.filter(c => c.category === category);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const exportData = targetCards.map(c => ({
        'Full Name': `${c.prefix || ''} ${c.firstName} ${c.lastName}`.trim(),
        'Company': c.company || '',
        'Position': c.title || '',
        'Email': c.email || '',
        'Phone': c.phone || '',
        'Country': c.country || '',
      }));

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");

      const fileName = `QS_Export_${category}_${new Date().toISOString().slice(0,10)}.xlsx`;
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      alert("匯出失敗");
    } finally {
      setIsExporting(false);
    }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-slate-900 font-sans">
      {/* Sidebar - 只在清單模式或桌面顯示 */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[420px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-10 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div>
                 <h2 className="text-xl font-black text-slate-800 tracking-tight">QS HUB</h2>
                 <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Digital Scanner</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-full text-slate-400"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-2">
            <Tab color="indigo" label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <Tab color="slate" label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <Tab color="slate" label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-4">
           <div className="flex items-center justify-between py-2">
              <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">{activeCategory}s ({cards.filter(c => c.category === activeCategory).length})</h3>
              <button 
                onClick={() => handleExport(activeCategory)} 
                disabled={isExporting}
                className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 text-white rounded-xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all shadow-xl shadow-slate-200"
              >
                <i className={`fa-solid ${isExporting ? 'fa-circle-notch fa-spin' : 'fa-download'}`}></i>
                {isExporting ? '處理中' : '下載 EXCEL'}
              </button>
           </div>

           <div className="space-y-4 pb-10">
             {cards.filter(c => c.category === activeCategory).map(c => (
                <div 
                  key={c.id} 
                  onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                  className={`relative p-6 rounded-[2rem] cursor-pointer overflow-hidden transition-all duration-300 ${selectedCardId === c.id ? 'bg-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-gradient-to-br from-indigo-500 to-indigo-700 text-white shadow-lg hover:shadow-xl hover:-translate-y-1'}`}
                >
                  <div className="absolute top-0 right-0 p-4 opacity-10"><i className="fa-solid fa-id-card text-5xl"></i></div>
                  <div className="relative z-10">
                    <div className="font-black text-xl mb-1 tracking-tight">{c.firstName} {c.lastName}</div>
                    <div className="text-[11px] font-bold opacity-80 truncate uppercase tracking-widest">{c.company}</div>
                  </div>
                </div>
             ))}
           </div>
        </div>
      </aside>

      {/* Main Container */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {/* Top Header - 在手機核對模式隱藏，以節省空間 */}
        <header className={`h-16 lg:h-20 px-4 lg:px-10 border-b border-slate-50 flex items-center justify-between bg-white/90 backdrop-blur-xl sticky top-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`}>
           <div className="flex items-center gap-4 w-full">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-indigo-50 rounded-xl text-indigo-600"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-2xl overflow-x-auto no-scrollbar">
                <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-upload" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        {/* Content Area - 捲動優化核心 */}
        <div className={`flex-1 relative ${viewMode === 'detail' ? '' : 'overflow-y-auto custom-scrollbar'}`}>
          {viewMode === 'camera' ? (
            <div className="h-full p-4 lg:p-10">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center p-8">
              <div 
