const Field = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(10);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="group space-y-3">
      <div className="flex items-center justify-between px-1">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-300 group-hover:text-indigo-500 transition-colors`}></i> {label}
        </label>
        {value && <button onClick={copy} className="text-[10px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all">{copied ? 'Copied' : 'Copy'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-5 lg:p-6 rounded-[1.8rem] font-bold text-slate-800 text-base tracking-tight shadow-sm group-hover:border-indigo-100 group-hover:bg-indigo-50/20 transition-all">
        {value || <span className="text-slate-300 font-normal italic">--- Data missing ---</span>}
      </div>
    </div>
  );
};

