                  </div>
               </div>

               <div className="flex-1 overflow-y-auto custom-scrollbar bg-white relative">
                  <div className={`p-8 lg:p-12 space-y-10 ${isMobile ? 'pb-44' : 'pb-24'}`}>
                    <header className="border-b border-slate-50 pb-8">
                       <span className="inline-block px-3 py-1 bg-indigo-50 text-indigo-600 text-[9px] font-black uppercase tracking-[0.2em] rounded-md mb-4">QS Verified Data</span>
