                        <>
                          <Field label="Department (系所)" value={selectedCard.department} icon="fa-sitemap" />
                          <Field label="Subject (學科領域)" value={selectedCard.subject} icon="fa-book-open" />
                        </>
                      )}

                      {(selectedCard.category === 'employer' || selectedCard.category === 'staff') && (
                        <Field label="Industry (產業)" value={selectedCard.industry} icon="fa-industry" />
                      )}

                      <Field label="Email (電子郵件)" value={selectedCard.email} icon="fa-envelope" />
                      <Field label="Phone (Optional)" value={selectedCard.phone} icon="fa-phone" />
                      <Field label="Country or Territory" value={selectedCard.country} icon="fa-earth-asia" />
                      <Field label="Source" value={selectedCard.source} icon="fa-tag" />
                    </div>

                    <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 relative overflow-hidden">
                      <span className="block font-black text-[10px] text-slate-400 uppercase tracking-[0.2em] mb-4">AI 分析摘要 (僅限名片內容)</span>
                      <p className="text-sm text-slate-600 italic leading-relaxed break-all">{selectedCard.reasoning}</p>
                    </div>
                  </div>
               </div>

               {isMobile && (
                 <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-2xl border-t border-slate-50 z-[80] flex gap-3 shadow-2xl">
                    <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all">
                      核對無誤並返回
                    </button>
                    <button onClick={() => handleExport(selectedCard.category)} className="w-16 h-16 bg-slate-100 text-slate-400 rounded-2xl flex items-center justify-center active:scale-95 transition-all">
                      <i className="fa-solid fa-file-excel text-emerald-600"></i>
                    </button>
                 </div>
               )}
            </div>
          ) : null}
        </div>

        {isImageZoomed && selectedCard && (
          <div className="fixed inset-0 z-[300] bg-black/98 flex items-center justify-center p-4 overflow-hidden" onClick={() => setIsImageZoomed(false)}>
             <button onClick={() => setIsImageZoomed(false)} className="absolute top-10 right-10 w-14 h-14 bg-white/10 text-white rounded-full flex items-center justify-center backdrop-blur-2xl border border-white/20 z-[310]"><i className="fa-solid fa-xmark text-xl"></i></button>
             <div className="w-full h-full flex items-center justify-center overflow-auto no-scrollbar">
                <img src={selectedCard.imageUrl} className="max-w-none w-full lg:w-auto lg:h-[95vh] object-contain shadow-2xl transition-transform" style={{ transform: `rotate(${rotation}deg)` }} onClick={(e) => e.stopPropagation()} />
             </div>
          </div>
        )}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[90]" onClick={() => setIsSidebarOpen(false)} />}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .break-all { word-break: break-all; }
      `}</style>
    </div>
  );
};

const Field = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(10);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="group space-y-3">
      <div className="flex items-center justify-between px-1">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <i className={`fa-solid ${icon} text-indigo-300 transition-colors`}></i> {label}
        </label>
        {value && <button onClick={copy} className="text-[10px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all">{copied ? '已複製' : '複製內容'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-5 rounded-[1.8rem] font-bold text-slate-800 text-base tracking-tight shadow-sm group-hover:bg-indigo-50/20 transition-all break-all">
        {value || <span className="text-slate-300 font-normal italic">名片中無此資料</span>}
      </div>
    </div>
  );
};

const Tab = ({ color, label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${active ? `bg-${color}-50 border-indigo-600 text-indigo-700 shadow-md` : 'bg-white border-transparent text-slate-300'}`}>
    <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-60">{label}</span>
    <span className="text-base font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-5 rounded-xl transition-all font-black text-[10px] uppercase tracking-widest whitespace-nowrap ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden sm:inline">{label}</span>
  </button>
);

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = category === 'all' ? cards : cards.filter(c => c.category === category);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      let exportData: any[];

      if (category === 'all') {
        // 第四種格式：全資料總表
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Category': c.category,
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Job Title / Position': c.title || '',
          'Institution / Company': c.company || '',
          'Department': c.department || '',
          'Subject': c.subject || '',
          'Industry': c.industry || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone': c.phone || '',
          'AI Reasoning': c.reasoning || ''
        }));
      } else if (category === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Job Title': c.title || '',
          'Department': c.department || '',
          'Institution': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Subject': c.subject || '',
          'Phone (Optional)': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Position': c.title || '',
          'Industry': c.industry || '',
          'Company Name': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone (Optional)': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");

      const fileName = `QS_Export_${category}_${new Date().toISOString().slice(0,10)}.xlsx`;
      XLSX.writeFile(wb, fileName);
    } catch (err) {
      alert("匯出失敗: " + err);
    } finally {
      setIsExporting(false);
    }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-slate-900 font-sans">
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[420px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-6 lg:p-10 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100 shrink-0">
                 <i className="fa-solid fa-bahai text-2xl"></i>
               </div>
               <div className="min-w-0 overflow-hidden">
                 <h2 className="text-xl font-black text-slate-800 tracking-tight truncate">QS HUB</h2>
                 <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest block truncate">Scanner Utility</span>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 shrink-0"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-2 mb-4">
            <Tab color="indigo" label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <Tab color="indigo" label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <Tab color="indigo" label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <button 
            onClick={() => handleExport('all')}
            className="w-full py-3 px-4 bg-indigo-50 text-indigo-700 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] flex items-center justify-center gap-2 hover:bg-indigo-100 transition-colors shadow-sm"
          >
            <i className="fa-solid fa-file-export"></i>
            匯出全資料總表 ({cards.length})
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-4 bg-slate-50/30">
           <div className="flex items-center justify-between py-2">
              <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] truncate">{activeCategory} List</h3>
              <button 
