    if (value) {
      navigator.clipboard.writeText(value);
      setCopied(true);
      if (window.navigator.vibrate) window.navigator.vibrate(10);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="group space-y-3 min-w-0">
      <div className="flex items-center justify-between px-1">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 truncate">
          <i className={`fa-solid ${icon} text-indigo-300 transition-colors shrink-0`}></i> {label}
        </label>
        {value && <button onClick={copy} className="text-[10px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all shrink-0 ml-2">{copied ? '已複製' : '複製內容'}</button>}
