          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
               <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 shrink-0">
                 <i className="fa-solid fa-bahai text-lg"></i>
               </div>
               <div className="min-w-0 overflow-hidden">
                 <h2 className="text-base font-black text-slate-800 tracking-tight truncate uppercase">QS Hub</h2>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-8 h-8 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 shrink-0"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-1 mb-3">
            <CompactTab label="Emp" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Acad" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <button onClick={() => handleExport('all')} className="w-full py-2 px-3 bg-indigo-50 text-indigo-700 rounded-lg text-[9px] font-black uppercase tracking-[0.1em] flex items-center justify-center gap-2 hover:bg-indigo-100 transition-colors shadow-sm">
            <i className="fa-solid fa-table"></i> 匯出全資料總表
