          <div className="mt-2 pt-2 border-t border-indigo-100/50 flex items-start gap-2">
            <span className="text-[8px] px-1.5 py-0.5 bg-indigo-500 text-white rounded font-black uppercase shrink-0 mt-0.5 tracking-tighter">註解</span>
            <span className="text-xs font-bold text-indigo-600/80 leading-relaxed">{translation}</span>
