  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 重置旋轉狀態當選擇不同名片
  useEffect(() => {
    setRotation(0);
  }, [selectedCardId]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = category === 'all' ? cards : cards.filter(c => c.category === category);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      let exportData: any[];

      if (category === 'all') {
        exportData = targetCards.map(c => ({
          '來源': c.source || 'QS Hub Scanner',
          '類別': c.category,
          '原始稱謂': c.prefix || '',
          '原始職稱': c.title || '',
          '職稱中文註解': c.translations?.title || '',
          '原始公司/機構': c.company || '',
          '公司中文註解': c.translations?.company || '',
          '原始部門': c.department || '',
          '部門中文註解': c.translations?.department || '',
          '姓名': `${c.firstName} ${c.lastName}`,
          '電子郵件': c.email || '',
          '電話': c.phone || '',
          '國家/地區': c.country || '',
          '國家中文註解': c.translations?.country || '',
          'AI 歸納': c.reasoning || ''
        }));
      } else if (category === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Job Title': c.title || '',
          'Department': c.department || '',
          'Institution': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Subject': c.subject || '',
          'Phone (Optional)': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Position': c.title || '',
          'Industry': c.industry || '',
          'Company Name': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone (Optional)': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Data");
      XLSX.writeFile(wb, `Export_${category}_${Date.now()}.xlsx`);
    } catch (err) { alert(err); } finally { setIsExporting(false); }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-slate-900 font-sans">
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-4 lg:p-6 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
               <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 shrink-0">
                 <i className="fa-solid fa-bahai text-lg"></i>
               </div>
               <div className="min-w-0 overflow-hidden">
                 <h2 className="text-base font-black text-slate-800 tracking-tight truncate uppercase">QS Hub</h2>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-8 h-8 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 shrink-0"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-1 mb-3">
            <CompactTab label="Emp" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Acad" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <button onClick={() => handleExport('all')} className="w-full py-2 px-3 bg-indigo-50 text-indigo-700 rounded-lg text-[9px] font-black uppercase tracking-[0.1em] flex items-center justify-center gap-2 hover:bg-indigo-100 transition-colors shadow-sm">
            <i className="fa-solid fa-table"></i> 匯出全資料
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/20">
           {/* 改為雙排網格佈局 */}
           <div className="grid grid-cols-2 gap-1.5 pb-10">
             {cards.filter(c => c.category === activeCategory).map(c => (
                <div 
                  key={c.id} 
                  onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                  className={`group relative p-2.5 rounded-lg cursor-pointer overflow-hidden transition-all duration-200 border flex flex-col justify-between h-20 ${selectedCardId === c.id ? 'bg-indigo-600 border-indigo-600 shadow-md shadow-indigo-100' : 'bg-white border-slate-100 hover:border-indigo-200 hover:bg-indigo-50/30'}`}
                >
                  <div className={`absolute left-0 top-0 bottom-0 w-0.5 ${selectedCardId === c.id ? 'bg-white/40' : 'bg-indigo-400/20'}`}></div>
                  <div className="relative z-10 min-w-0 pl-0.5">
                    <div className={`font-bold text-[10px] mb-0.5 tracking-tight break-all line-clamp-1 ${selectedCardId === c.id ? 'text-white' : 'text-slate-800'}`}>{c.firstName} {c.lastName}</div>
                    <div className={`text-[8px] font-medium truncate uppercase tracking-wider ${selectedCardId === c.id ? 'text-white/70' : 'text-slate-400'}`}>
                      {c.company}
                    </div>
                  </div>
                  {c.translations?.company && c.translations.company !== c.company && (
                    <div className={`text-[7px] font-bold truncate ${selectedCardId === c.id ? 'text-white/40' : 'text-indigo-400'}`}>
                      {c.translations.company}
                    </div>
                  )}
                </div>
             ))}
           </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className={`h-14 lg:h-16 px-4 lg:px-8 border-b border-slate-50 flex items-center justify-between bg-white/90 backdrop-blur-xl sticky top-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`}>
           <div className="flex items-center gap-3 w-full min-w-0">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-9 h-9 flex items-center justify-center bg-indigo-50 rounded-lg text-indigo-600 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl overflow-x-auto no-scrollbar max-w-full">
                <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-upload" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className={`flex-1 relative overflow-hidden ${viewMode === 'detail' ? '' : 'overflow-y-auto custom-scrollbar'}`}>
          {viewMode === 'camera' ? (
            <div className="h-full p-4 lg:p-10"><CameraScanner onCapture={async (b64) => { 
                const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(id, await res.blob());
                setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center p-8">
              <div className="w-full max-w-lg p-10 lg:p-16 border-2 border-dashed border-slate-100 rounded-[2.5rem] bg-slate-50/50 hover:bg-indigo-50 hover:border-indigo-200 transition-all cursor-pointer text-center group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl group-hover:scale-110 transition-transform"><i className="fa-solid fa-cloud-arrow-up text-2xl text-indigo-600"></i></div>
                <h3 className="text-lg font-black text-slate-800 mb-1">上傳名片照片</h3>
                <p className="text-slate-400 text-[9px] font-black uppercase tracking-widest">點擊選取多張圖檔進行識別</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID(); filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1, plan };
                  });
                  setTasks(prev => [...prev, ...newTasks]); setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-xl mx-auto p-6 lg:p-12 space-y-4">
              <h2 className="font-black text-xl text-slate-800 mb-6">處理清單</h2>
              {tasks.map(t => (
                <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between shadow-sm overflow-hidden">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}><i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : 'fa-circle-notch fa-spin'}`}></i></div>
                    <div className="min-w-0">
                      <div className="font-bold text-slate-800 text-xs truncate break-all">{t.fileName}</div>
                      <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{t.status}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : selectedCard ? (
            <div className="h-full flex flex-col lg:flex-row bg-slate-50 overflow-hidden">
               {/* 旋轉容器優化：確保內容不超出格子 */}
               <div className={`relative flex flex-col bg-[#080d1a] overflow-hidden ${isMobile ? 'h-[35vh] shrink-0' : 'w-[45%] h-full p-6 lg:p-10 border-r border-slate-100'}`}>
                  <div className="absolute top-4 right-4 z-[70] flex gap-2">
                    <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-white/10 backdrop-blur-xl rounded-lg flex items-center justify-center text-white border border-white/10 active:scale-90 transition-all"><i className="fa-solid fa-rotate-right"></i></button>
                    <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg active:scale-90 transition-all"><i className="fa-solid fa-maximize"></i></button>
                  </div>
                  {/* 使用 flex-col 與 max-w-full 確保旋轉時影像能正確縮放適應容器 */}
                  <div className="flex-1 flex items-center justify-center p-4 relative overflow-hidden" onClick={() => setIsImageZoomed(true)}>
                    <div className="relative w-full h-full flex items-center justify-center">
                       <img 
                         src={selectedCard.imageUrl} 
                         className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)]" 
                         style={{ 
                           transform: `rotate(${rotation}deg)`,
                           // 當旋轉 90 或 270 度時，如果影像本來是橫向的，可能會超出垂直空間。
                           // 這裡使用 scale 來平衡容器長寬比的差異。
                           scale: (rotation % 180 !== 0) ? '0.8' : '1'
                         }} 
                       />
                    </div>
                  </div>
                  <div className="absolute bottom-4 left-0 right-0 text-center">
                    <span className="text-[8px] font-black text-white/20 uppercase tracking-[0.4em]">Card Visual Reference</span>
                  </div>
               </div>

               <div className="flex-1 overflow-y-auto custom-scrollbar bg-white relative">
                  <div className={`p-6 lg:p-10 space-y-8 ${isMobile ? 'pb-40' : 'pb-24'}`}>
                    <header className="border-b border-slate-50 pb-6 min-w-0">
                       <span className="inline-block px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[8px] font-black uppercase tracking-[0.2em] rounded mb-3">AI 識別結果</span>
                       <h1 className="text-2xl lg:text-3xl font-black text-slate-900 tracking-tighter mb-1 break-all uppercase">
                        {selectedCard.prefix ? selectedCard.prefix + ' ' : ''}{selectedCard.firstName} {selectedCard.lastName}
                       </h1>
                       <div className="flex flex-wrap gap-2 items-center">
                        <p className="text-lg font-bold text-indigo-500 break-all">{selectedCard.title || '無職稱'}</p>
                        {selectedCard.translations?.title && selectedCard.translations.title !== selectedCard.title && (
                          <span className="text-[10px] px-2 py-0.5 bg-slate-100 text-slate-500 rounded font-bold">({selectedCard.translations.title})</span>
                        )}
                       </div>
                    </header>

                    <div className="grid gap-4">
                      <Field 
                        label={selectedCard.category === 'academic' ? "Institution (原始機構)" : "Company (原始公司)"} 
                        value={selectedCard.company} 
                        translation={selectedCard.translations?.company}
                        icon="fa-building" 
                      />

                      {selectedCard.category === 'academic' && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <Field label="Department (原始部門)" value={selectedCard.department} translation={selectedCard.translations?.department} icon="fa-sitemap" />
                          <Field label="Subject (學科領域)" value={selectedCard.subject} translation={selectedCard.translations?.subject} icon="fa-book-open" />
                        </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Industry (產業)" value={selectedCard.industry} translation={selectedCard.translations?.industry} icon="fa-industry" />
                        <Field label="Country (國家)" value={selectedCard.country} translation={selectedCard.translations?.country} icon="fa-earth-asia" />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Email (電子郵件)" value={selectedCard.email} icon="fa-envelope" />
                        <Field label="Phone (電話)" value={selectedCard.phone} icon="fa-phone" />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Mobile (手機)" value={selectedCard.mobile} icon="fa-mobile-screen" />
                        <Field label="Website (網站)" value={selectedCard.website} icon="fa-globe" />
                      </div>

                      <Field label="Address (地址)" value={selectedCard.address} icon="fa-location-dot" />
                    </div>

                    <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                      <span className="block font-black text-[9px] text-slate-400 uppercase tracking-[0.2em] mb-3">AI 分析摘要 (繁體中文)</span>
                      <p className="text-xs text-slate-600 leading-relaxed break-all font-medium whitespace-pre-wrap">{selectedCard.reasoning}</p>
                    </div>
                  </div>
               </div>

               {isMobile && (
                 <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-2xl border-t border-slate-50 z-[80] flex gap-2 shadow-2xl">
                    <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-900 text-white py-3.5 rounded-xl font-black text-[10px] uppercase tracking-[0.1em] shadow-xl">完成並返回</button>
                    <button onClick={() => handleExport(selectedCard.category)} className="w-12 h-12 bg-white border border-slate-200 text-emerald-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-file-excel"></i></button>
                 </div>
               )}
            </div>
          ) : null}
        </div>

        {isImageZoomed && selectedCard && (
          <div className="fixed inset-0 z-[300] bg-black/98 flex items-center justify-center p-4 overflow-hidden" onClick={() => setIsImageZoomed(false)}>
             <button onClick={() => setIsImageZoomed(false)} className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center backdrop-blur-2xl border border-white/20 z-[310]"><i className="fa-solid fa-xmark text-lg"></i></button>
             <div className="w-full h-full flex items-center justify-center overflow-auto no-scrollbar">
                <img 
                  src={selectedCard.imageUrl} 
                  className="max-w-none w-full lg:w-auto lg:h-[95vh] object-contain shadow-2xl transition-transform duration-500" 
                  style={{ transform: `rotate(${rotation}deg)` }} 
                  onClick={(e) => e.stopPropagation()} 
                />
             </div>
          </div>
        )}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[90]" onClick={() => setIsSidebarOpen(false)} />}
      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .break-all { word-break: break-all; }
        .line-clamp-1 { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
      `}</style>
    </div>
  );
};

const Field = ({ label, value, translation, icon }: { label: string, value?: string, translation?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = (txt?: string) => {
    if (txt) {
      navigator.clipboard.writeText(txt);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="group space-y-2 min-w-0">
      <div className="flex items-center justify-between px-0.5">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 truncate">
          <i className={`fa-solid ${icon} text-indigo-300 shrink-0`}></i> {label}
        </label>
        {value && <button onClick={() => copy(value)} className="text-[9px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all shrink-0 ml-2">{copied ? '已複製' : '複製'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl font-bold text-slate-800 text-[13px] tracking-tight shadow-sm group-hover:bg-indigo-50/20 transition-all break-all relative">
        {value || <span className="text-slate-300 font-normal italic text-xs">無原始資料</span>}
        {translation && translation !== value && (
          <div className="mt-2 pt-2 border-t border-indigo-100/50 flex items-start gap-2">
            <span className="text-[7px] px-1 py-0.5 bg-indigo-500 text-white rounded font-black uppercase shrink-0 mt-0.5 tracking-tighter">註解</span>
            <span className="text-[11px] font-bold text-indigo-600/80 leading-relaxed">{translation}</span>
          </div>
        )}
      </div>
    </div>
  );
};

const CompactTab = ({ label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center py-2 px-1 rounded-lg border transition-all min-w-0 ${active ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-100 text-slate-300'}`}>
    <span className="text-[8px] font-black uppercase tracking-widest mb-0.5 truncate w-full">{label}</span>
    <span className="text-xs font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-1.5 py-1.5 px-3.5 rounded-lg transition-all font-black text-[9px] uppercase tracking-widest whitespace-nowrap shrink-0 ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden sm:inline">{label}</span>
  </button>
);

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 重置旋轉狀態當選擇不同名片
  useEffect(() => {
    setRotation(0);
  }, [selectedCardId]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', task.plan || 'free');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const handleExport = async (category: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = category === 'all' ? cards : cards.filter(c => c.category === category);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      let exportData: any[];

      if (category === 'all') {
        exportData = targetCards.map(c => ({
          '來源': c.source || 'QS Hub Scanner',
          '類別': c.category,
          '原始稱謂': c.prefix || '',
          '原始職稱': c.title || '',
          '職稱中文註解': c.translations?.title || '',
          '原始公司/機構': c.company || '',
          '公司中文註解': c.translations?.company || '',
          '原始部門': c.department || '',
          '部門中文註解': c.translations?.department || '',
          '姓名': `${c.firstName} ${c.lastName}`,
          '電子郵件': c.email || '',
          '電話': c.phone || '',
          '國家/地區': c.country || '',
          '國家中文註解': c.translations?.country || '',
          'AI 歸納': c.reasoning || ''
        }));
      } else if (category === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Job Title': c.title || '',
          'Department': c.department || '',
          'Institution': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Subject': c.subject || '',
          'Phone (Optional)': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Position': c.title || '',
          'Industry': c.industry || '',
          'Company Name': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone (Optional)': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Data");
      XLSX.writeFile(wb, `Export_${category}_${Date.now()}.xlsx`);
    } catch (err) { alert(err); } finally { setIsExporting(false); }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-slate-900 font-sans">
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-4 lg:p-6 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
               <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 shrink-0">
                 <i className="fa-solid fa-bahai text-lg"></i>
               </div>
               <div className="min-w-0 overflow-hidden">
                 <h2 className="text-base font-black text-slate-800 tracking-tight truncate uppercase">QS Hub</h2>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-8 h-8 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 shrink-0"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-1 mb-3">
            <CompactTab label="Emp" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Acad" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <button onClick={() => handleExport('all')} className="w-full py-2 px-3 bg-indigo-50 text-indigo-700 rounded-lg text-[9px] font-black uppercase tracking-[0.1em] flex items-center justify-center gap-2 hover:bg-indigo-100 transition-colors shadow-sm">
            <i className="fa-solid fa-table"></i> 匯出全資料
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/20">
           {/* 改為雙排網格佈局 */}
           <div className="grid grid-cols-2 gap-1.5 pb-10">
             {cards.filter(c => c.category === activeCategory).map(c => (
                <div 
                  key={c.id} 
                  onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                  className={`group relative p-2.5 rounded-lg cursor-pointer overflow-hidden transition-all duration-200 border flex flex-col justify-between h-20 ${selectedCardId === c.id ? 'bg-indigo-600 border-indigo-600 shadow-md shadow-indigo-100' : 'bg-white border-slate-100 hover:border-indigo-200 hover:bg-indigo-50/30'}`}
                >
                  <div className={`absolute left-0 top-0 bottom-0 w-0.5 ${selectedCardId === c.id ? 'bg-white/40' : 'bg-indigo-400/20'}`}></div>
                  <div className="relative z-10 min-w-0 pl-0.5">
                    <div className={`font-bold text-[10px] mb-0.5 tracking-tight break-all line-clamp-1 ${selectedCardId === c.id ? 'text-white' : 'text-slate-800'}`}>{c.firstName} {c.lastName}</div>
                    <div className={`text-[8px] font-medium truncate uppercase tracking-wider ${selectedCardId === c.id ? 'text-white/70' : 'text-slate-400'}`}>
                      {c.company}
                    </div>
                  </div>
                  {c.translations?.company && c.translations.company !== c.company && (
                    <div className={`text-[7px] font-bold truncate ${selectedCardId === c.id ? 'text-white/40' : 'text-indigo-400'}`}>
                      {c.translations.company}
                    </div>
                  )}
                </div>
             ))}
           </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className={`h-14 lg:h-16 px-4 lg:px-8 border-b border-slate-50 flex items-center justify-between bg-white/90 backdrop-blur-xl sticky top-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`}>
           <div className="flex items-center gap-3 w-full min-w-0">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-9 h-9 flex items-center justify-center bg-indigo-50 rounded-lg text-indigo-600 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl overflow-x-auto no-scrollbar max-w-full">
                <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-upload" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className={`flex-1 relative overflow-hidden ${viewMode === 'detail' ? '' : 'overflow-y-auto custom-scrollbar'}`}>
          {viewMode === 'camera' ? (
            <div className="h-full p-4 lg:p-10"><CameraScanner onCapture={async (b64) => { 
                const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(id, await res.blob());
                setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex items-center justify-center p-8">
              <div className="w-full max-w-lg p-10 lg:p-16 border-2 border-dashed border-slate-100 rounded-[2.5rem] bg-slate-50/50 hover:bg-indigo-50 hover:border-indigo-200 transition-all cursor-pointer text-center group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl group-hover:scale-110 transition-transform"><i className="fa-solid fa-cloud-arrow-up text-2xl text-indigo-600"></i></div>
                <h3 className="text-lg font-black text-slate-800 mb-1">上傳名片照片</h3>
                <p className="text-slate-400 text-[9px] font-black uppercase tracking-widest">點擊選取多張圖檔進行識別</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID(); filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1, plan };
                  });
                  setTasks(prev => [...prev, ...newTasks]); setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-xl mx-auto p-6 lg:p-12 space-y-4">
              <h2 className="font-black text-xl text-slate-800 mb-6">處理清單</h2>
              {tasks.map(t => (
                <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between shadow-sm overflow-hidden">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}><i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : 'fa-circle-notch fa-spin'}`}></i></div>
                    <div className="min-w-0">
                      <div className="font-bold text-slate-800 text-xs truncate break-all">{t.fileName}</div>
                      <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{t.status}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : selectedCard ? (
            <div className="h-full flex flex-col lg:flex-row bg-slate-50 overflow-hidden">
               {/* 旋轉容器優化：確保內容不超出格子 */}
               <div className={`relative flex flex-col bg-[#080d1a] overflow-hidden ${isMobile ? 'h-[35vh] shrink-0' : 'w-[45%] h-full p-6 lg:p-10 border-r border-slate-100'}`}>
                  <div className="absolute top-4 right-4 z-[70] flex gap-2">
                    <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-white/10 backdrop-blur-xl rounded-lg flex items-center justify-center text-white border border-white/10 active:scale-90 transition-all"><i className="fa-solid fa-rotate-right"></i></button>
                    <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg active:scale-90 transition-all"><i className="fa-solid fa-maximize"></i></button>
                  </div>
                  {/* 使用 flex-col 與 max-w-full 確保旋轉時影像能正確縮放適應容器 */}
                  <div className="flex-1 flex items-center justify-center p-4 relative overflow-hidden" onClick={() => setIsImageZoomed(true)}>
                    <div className="relative w-full h-full flex items-center justify-center">
                       <img 
                         src={selectedCard.imageUrl} 
                         className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)]" 
                         style={{ 
                           transform: `rotate(${rotation}deg)`,
                           // 當旋轉 90 或 270 度時，如果影像本來是橫向的，可能會超出垂直空間。
                           // 這裡使用 scale 來平衡容器長寬比的差異。
                           scale: (rotation % 180 !== 0) ? '0.8' : '1'
                         }} 
                       />
                    </div>
                  </div>
                  <div className="absolute bottom-4 left-0 right-0 text-center">
                    <span className="text-[8px] font-black text-white/20 uppercase tracking-[0.4em]">Card Visual Reference</span>
                  </div>
               </div>

               <div className="flex-1 overflow-y-auto custom-scrollbar bg-white relative">
                  <div className={`p-6 lg:p-10 space-y-8 ${isMobile ? 'pb-40' : 'pb-24'}`}>
                    <header className="border-b border-slate-50 pb-6 min-w-0">
                       <span className="inline-block px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[8px] font-black uppercase tracking-[0.2em] rounded mb-3">AI 識別結果</span>
                       <h1 className="text-2xl lg:text-3xl font-black text-slate-900 tracking-tighter mb-1 break-all uppercase">
                        {selectedCard.prefix ? selectedCard.prefix + ' ' : ''}{selectedCard.firstName} {selectedCard.lastName}
                       </h1>
                       <div className="flex flex-wrap gap-2 items-center">
                        <p className="text-lg font-bold text-indigo-500 break-all">{selectedCard.title || '無職稱'}</p>
                        {selectedCard.translations?.title && selectedCard.translations.title !== selectedCard.title && (
                          <span className="text-[10px] px-2 py-0.5 bg-slate-100 text-slate-500 rounded font-bold">({selectedCard.translations.title})</span>
                        )}
                       </div>
                    </header>

                    <div className="grid gap-4">
                      <Field 
                        label={selectedCard.category === 'academic' ? "Institution (原始機構)" : "Company (原始公司)"} 
                        value={selectedCard.company} 
                        translation={selectedCard.translations?.company}
                        icon="fa-building" 
                      />

                      {selectedCard.category === 'academic' && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <Field label="Department (原始部門)" value={selectedCard.department} translation={selectedCard.translations?.department} icon="fa-sitemap" />
                          <Field label="Subject (學科領域)" value={selectedCard.subject} translation={selectedCard.translations?.subject} icon="fa-book-open" />
                        </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Industry (產業)" value={selectedCard.industry} translation={selectedCard.translations?.industry} icon="fa-industry" />
                        <Field label="Country (國家)" value={selectedCard.country} translation={selectedCard.translations?.country} icon="fa-earth-asia" />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Email (電子郵件)" value={selectedCard.email} icon="fa-envelope" />
                        <Field label="Phone (電話)" value={selectedCard.phone} icon="fa-phone" />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Field label="Mobile (手機)" value={selectedCard.mobile} icon="fa-mobile-screen" />
                        <Field label="Website (網站)" value={selectedCard.website} icon="fa-globe" />
                      </div>

                      <Field label="Address (地址)" value={selectedCard.address} icon="fa-location-dot" />
                    </div>

                    <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100">
                      <span className="block font-black text-[9px] text-slate-400 uppercase tracking-[0.2em] mb-3">AI 分析摘要 (繁體中文)</span>
                      <p className="text-xs text-slate-600 leading-relaxed break-all font-medium whitespace-pre-wrap">{selectedCard.reasoning}</p>
                    </div>
                  </div>
               </div>

               {isMobile && (
                 <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-2xl border-t border-slate-50 z-[80] flex gap-2 shadow-2xl">
                    <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-900 text-white py-3.5 rounded-xl font-black text-[10px] uppercase tracking-[0.1em] shadow-xl">完成並返回</button>
                    <button onClick={() => handleExport(selectedCard.category)} className="w-12 h-12 bg-white border border-slate-200 text-emerald-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-file-excel"></i></button>
                 </div>
               )}
            </div>
          ) : null}
        </div>

        {isImageZoomed && selectedCard && (
          <div className="fixed inset-0 z-[300] bg-black/98 flex items-center justify-center p-4 overflow-hidden" onClick={() => setIsImageZoomed(false)}>
             <button onClick={() => setIsImageZoomed(false)} className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center backdrop-blur-2xl border border-white/20 z-[310]"><i className="fa-solid fa-xmark text-lg"></i></button>
             <div className="w-full h-full flex items-center justify-center overflow-auto no-scrollbar">
                <img 
                  src={selectedCard.imageUrl} 
                  className="max-w-none w-full lg:w-auto lg:h-[95vh] object-contain shadow-2xl transition-transform duration-500" 
                  style={{ transform: `rotate(${rotation}deg)` }} 
                  onClick={(e) => e.stopPropagation()} 
                />
             </div>
          </div>
        )}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[90]" onClick={() => setIsSidebarOpen(false)} />}
      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .break-all { word-break: break-all; }
        .line-clamp-1 { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
      `}</style>
    </div>
  );
};

const Field = ({ label, value, translation, icon }: { label: string, value?: string, translation?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = (txt?: string) => {
    if (txt) {
      navigator.clipboard.writeText(txt);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="group space-y-2 min-w-0">
      <div className="flex items-center justify-between px-0.5">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 truncate">
          <i className={`fa-solid ${icon} text-indigo-300 shrink-0`}></i> {label}
        </label>
        {value && <button onClick={() => copy(value)} className="text-[9px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all shrink-0 ml-2">{copied ? '已複製' : '複製'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl font-bold text-slate-800 text-[13px] tracking-tight shadow-sm group-hover:bg-indigo-50/20 transition-all break-all relative">
        {value || <span className="text-slate-300 font-normal italic text-xs">無原始資料</span>}
