            <CompactTab label="Acad" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

