            <button onClick={() => handleExport(activeCategory)} className="py-2 px-1 bg-emerald-50 text-emerald-700 rounded-lg text-[8px] font-black uppercase tracking-tight flex items-center justify-center gap-1 hover:bg-emerald-100 transition-colors shadow-sm">
