        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Position': c.title || '',
          'Industry': c.industry || '',
          'Company Name': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "QS_Data_Export");
      XLSX.writeFile(wb, `QS_Export_${targetCategory}_${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert(err); } finally { setIsExporting(false); }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-white text-slate-900 font-sans">
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-100 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-4 lg:p-6 bg-white border-b border-slate-50 shrink-0">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
               <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 shrink-0">
                 <i className="fa-solid fa-bahai text-lg"></i>
               </div>
               <div className="min-w-0 overflow-hidden">
                 <h2 className="text-base font-black text-slate-800 tracking-tight truncate uppercase">QS Hub</h2>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-8 h-8 flex items-center justify-center bg-slate-50 rounded-full text-slate-400 shrink-0"><i className="fa-solid fa-xmark"></i></button>}
          </div>

          <div className="grid grid-cols-3 gap-1 mb-3">
            <CompactTab label="Emp" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Acad" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <div className="grid grid-cols-2 gap-2">
            <button onClick={() => handleExport('all')} className="py-2 px-1 bg-indigo-50 text-indigo-700 rounded-lg text-[8px] font-black uppercase tracking-tight flex items-center justify-center gap-1 hover:bg-indigo-100 transition-colors shadow-sm">
              <i className="fa-solid fa-table"></i> 全資料
            </button>
            <button onClick={() => handleExport(activeCategory)} className="py-2 px-1 bg-emerald-50 text-emerald-700 rounded-lg text-[8px] font-black uppercase tracking-tight flex items-center justify-center gap-1 hover:bg-emerald-100 transition-colors shadow-sm">
              <i className="fa-solid fa-file-excel"></i> 匯出{activeCategory}
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/20">
           <div className="grid grid-cols-2 gap-1.5 pb-10">
