      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className={`h-14 lg:h-16 px-4 lg:px-8 border-b border-slate-50 flex items-center justify-between bg-white/90 backdrop-blur-xl sticky top-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`}>
           <div className="flex items-center gap-3 w-full min-w-0">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-9 h-9 flex items-center justify-center bg-indigo-50 rounded-lg text-indigo-600 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
