            <div className="h-full p-4 lg:p-10"><CameraScanner onCapture={async (b64) => { 
                const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(id, await res.blob());
                setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan }]);
                setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
