              <div className="w-full max-w-lg p-10 lg:p-16 border-2 border-dashed border-slate-100 rounded-[2.5rem] bg-slate-50/50 hover:bg-indigo-50 hover:border-indigo-200 transition-all cursor-pointer text-center group" onClick={() => fileInputRef.current?.click()}>
