const Field = ({ label, value, translation, icon }: { label: string, value?: string, translation?: string, icon: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = (txt?: string) => {
    if (txt) {
      navigator.clipboard.writeText(txt);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
    }
  };

  const hasValue = Boolean(value && value.trim().length > 0);

  return (
    <div className="group space-y-2 min-w-0">
      <div className="flex items-center justify-between px-0.5">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 truncate">
          <i className={`fa-solid ${icon} text-indigo-300 shrink-0`}></i> {label}
        </label>
        {hasValue && <button onClick={() => copy(value)} className="text-[9px] font-black text-indigo-500 uppercase tracking-widest active:opacity-50 transition-all shrink-0 ml-2">{copied ? '已複製' : '複製'}</button>}
      </div>
      <div className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl font-bold text-slate-800 text-[13px] tracking-tight shadow-sm group-hover:bg-indigo-50/20 transition-all break-all relative">
        {hasValue ? value : <span className="text-slate-300 font-normal italic text-xs">無原始資料</span>}

        {hasValue && translation && translation.trim() !== "" && translation !== value && (
          <div className="mt-2 pt-2 border-t border-indigo-100/50 flex items-start gap-2">
            <span className="text-[7px] px-1 py-0.5 bg-indigo-500 text-white rounded font-black uppercase shrink-0 mt-0.5 tracking-tighter">譯名</span>
            <span className="text-[11px] font-bold text-indigo-600/80 leading-relaxed">{translation}</span>
          </div>
        )}
      </div>
    </div>
  );
};

const CompactTab = ({ label, active, count, onClick }: any) => (
