    <span className="text-[8px] font-black uppercase tracking-widest mb-0.5 truncate w-full">{label}</span>
    <span className="text-xs font-black">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-1.5 py-1.5 px-3.5 rounded-lg transition-all font-black text-[9px] uppercase tracking-widest whitespace-nowrap shrink-0 ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span className="hidden sm:inline">{label}</span>
