                 <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-xl border-t border-slate-200 z-[80] flex gap-3 shadow-[0_-5px_20px_rgba(0,0,0,0.05)]">
                    <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-900 text-white py-4 rounded-xl font-bold text-xs uppercase tracking-widest shadow-lg active:scale-[0.98] transition-all">返回列表</button>
