// 優化後的欄位組件
const Field = React.memo(({ label, value, translation, icon, className }: { label: string, value?: string, translation?: string, icon?: string, className?: string }) => {
  const [copied, setCopied] = useState(false);
  const copy = (txt?: string) => {
    if (txt) {
      navigator.clipboard.writeText(txt);
      setCopied(true); setTimeout(() => setCopied(false), 2000);
    }
  };

  const hasValue = Boolean(value && value.trim().length > 0);

  return (
    <div className={`group min-w-0 ${className}`}>
      <div className="flex items-center justify-between mb-1.5 px-0.5">
        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
          {icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}
        </label>
        {hasValue && (
          <button onClick={() => copy(value)} className={`text-[9px] font-bold uppercase tracking-wider transition-all flex items-center gap-1 ${copied ? 'text-emerald-500' : 'text-indigo-400 opacity-0 group-hover:opacity-100'}`}>
            {copied ? <><i className="fa-solid fa-check"></i> Copied</> : <><i className="fa-regular fa-copy"></i> Copy</>}
          </button>
        )}
      </div>
      <div className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl transition-all hover:border-indigo-300 hover:bg-white hover:shadow-md group-hover:shadow-indigo-100/50 relative">
        <div className={`text-[14px] font-semibold leading-relaxed break-all ${hasValue ? 'text-slate-700' : 'text-slate-300 italic'}`}>
            {hasValue ? value : 'N/A'}
        </div>

        {hasValue && translation && translation.trim() !== "" && translation !== value && (
          <div className="mt-2.5 pt-2.5 border-t border-slate-100 flex items-start gap-2">
            <span className="text-[9px] font-bold text-indigo-400 uppercase tracking-wider shrink-0 mt-0.5">ZH</span>
            <span className="text-xs font-medium text-slate-500">{translation}</span>
          </div>
        )}
      </div>
    </div>
  );
});

