type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

export default App;

import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
    if (videoRef.current) videoRef.current.srcObject = null;
  };

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    stopTracks();

    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } }, 
        audio: false 
      });

      setStream(mediaStream);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().then(() => {
            setIsReady(true);
            setIsLoading(false);
          });
        };
      }
    } catch (err: any) {
      setIsLoading(false);
      setError("無法存取相機，請檢查瀏覽器隱私權設定。");
    }
  };

  useEffect(() => {
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        onCapture(canvas.toDataURL('image/jpeg', 0.9).split(',')[1]);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2.5rem] lg:rounded-[3rem] overflow-hidden relative shadow-2xl shadow-indigo-500/10 border border-slate-800 min-h-[500px]">
      <video ref={videoRef} autoPlay playsInline muted className={`h-full w-full object-cover transition-all duration-1000 ease-out ${isReady ? 'opacity-100 scale-100' : 'opacity-0 scale-105'}`} />

      {!isReady && (
        <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center bg-slate-900 z-10">
          <div className="w-20 h-20 bg-indigo-500/10 rounded-3xl flex items-center justify-center mb-8 text-indigo-400 shadow-[0_0_40px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20">
             {isLoading ? <i className="fa-solid fa-bahai fa-spin text-3xl"></i> : <i className="fa-solid fa-camera text-3xl"></i>}
          </div>
          <h3 className="text-white font-bold text-2xl mb-3 tracking-tight">AI 視覺掃描</h3>
          <p className="text-slate-400 text-sm mb-10 leading-relaxed px-4 max-w-sm">{error || (isLoading ? "正在啟動高畫質鏡頭..." : "請將名片水平對準框線，系統將自動進行邊緣偵測與 OCR 識別。")}</p>
          {!isLoading && <button onClick={startCamera} className="bg-white text-slate-900 py-4 px-10 rounded-2xl font-bold shadow-xl shadow-white/10 active:scale-95 transition-all text-sm tracking-wide">開啟相機</button>}
        </div>
      )}

      {isReady && (
        <>
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center bg-black/20">
             {/* Backdrop Overlay */}
             <div className="absolute inset-0 border-[40px] border-slate-900/50 backdrop-blur-[2px] mask-image-center"></div>

             <div className="w-[85%] max-w-md aspect-[1.586/1] border border-white/20 rounded-2xl relative shadow-[0_0_0_9999px_rgba(15,23,42,0.6)] overflow-hidden">
                {/* Frame Corners */}
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-400 -translate-x-0.5 -translate-y-0.5 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-400 translate-x-0.5 -translate-y-0.5 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-400 -translate-x-0.5 translate-y-0.5 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-400 translate-x-0.5 translate-y-0.5 rounded-br-lg"></div>

                {/* Scanning Line */}
                <div className="absolute top-0 left-0 w-full h-0.5 bg-indigo-400 shadow-[0_0_15px_rgba(129,140,248,0.8)] animate-[scan_2.5s_infinite_linear] opacity-80"></div>
             </div>

             <div className="absolute bottom-32 bg-black/60 backdrop-blur-md px-4 py-1.5 rounded-full border border-white/10 text-white/80 text-[10px] font-bold uppercase tracking-widest">
                Align Business Card
             </div>
          </div>

          <div className="absolute bottom-10 flex flex-col items-center w-full z-20 gap-4">
            <button onClick={capture} className="w-20 h-20 rounded-full bg-white/10 border-[6px] border-white/30 p-1.5 active:scale-90 transition-all shadow-2xl hover:bg-white/20 hover:border-white/50 backdrop-blur-sm">
              <div className="w-full h-full rounded-full bg-white flex items-center justify-center shadow-inner">
                <div className="w-14 h-14 rounded-full border-2 border-slate-100 flex items-center justify-center">
                    <i className="fa-solid fa-camera text-slate-800 text-xl"></i>
                </div>
              </div>
            </button>
          </div>

          <button onClick={() => { stopTracks(); onClose(); }} className="absolute top-8 right-8 w-12 h-12 bg-black/40 text-white rounded-full flex items-center justify-center backdrop-blur-md border border-white/10 active:scale-90 transition-all z-20 hover:bg-black/60">
            <i className="fa-solid fa-xmark text-lg"></i>
          </button>
        </>
      )}
      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan { 
          0%, 100% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

